const BUNDLED_COMPLETE_SURAHS: Record<number, QuranAyahItem[]> = {"36":[{"number":1,"arabic":"بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ يسٓ","translationFa":"یس."},{"number":2,"arabic":"وَٱلْقُرْءَانِ ٱلْحَكِيمِ","translationFa":"سوگند به قرآن حکیم."},{"number":3,"arabic":"إِنَّكَ لَمِنَ ٱلْمُرْسَلِينَ","translationFa":"که تو قطعاً از رسولان (خداوند) هستی،"},{"number":4,"arabic":"عَلَىٰ صِرَٰطٍۢ مُّسْتَقِيمٍۢ","translationFa":"بر راهی راست (قرار داری)؛"},{"number":5,"arabic":"تَنزِيلَ ٱلْعَزِيزِ ٱلرَّحِيمِ","translationFa":"این قرآنی است که از سوی خداوند عزیز و رحیم نازل شده است‌"},{"number":6,"arabic":"لِتُنذِرَ قَوْمًۭا مَّآ أُنذِرَ ءَابَآؤُهُمْ فَهُمْ غَٰفِلُونَ","translationFa":"تا قومی را بیم دهی که پدرانشان انذار نشدند، از این رو آنان غافلند!"},{"number":7,"arabic":"لَقَدْ حَقَّ ٱلْقَوْلُ عَلَىٰٓ أَكْثَرِهِمْ فَهُمْ لَا يُؤْمِنُونَ","translationFa":"فرمان (الهی) درباره بیشتر آنها تحقق یافته، به همین جهت ایمان نمی‌آورند!"},{"number":8,"arabic":"إِنَّا جَعَلْنَا فِىٓ أَعْنَٰقِهِمْ أَغْلَٰلًۭا فَهِىَ إِلَى ٱلْأَذْقَانِ فَهُم مُّقْمَحُونَ","translationFa":"ما در گردنهای آنان غلهایی قرار دادیم که تا چانه‌ها ادامه دارد و سرهای آنان را به بالا نگاه داشته است!"},{"number":9,"arabic":"وَجَعَلْنَا مِنۢ بَيْنِ أَيْدِيهِمْ سَدًّۭا وَمِنْ خَلْفِهِمْ سَدًّۭا فَأَغْشَيْنَٰهُمْ فَهُمْ لَا يُبْصِرُونَ","translationFa":"و در پیش روی آنان سدّی قرار دادیم، و در پشت سرشان سدّی؛ و چشمانشان را پوشانده‌ایم، لذا نمی‌بینند!"},{"number":10,"arabic":"وَسَوَآءٌ عَلَيْهِمْ ءَأَنذَرْتَهُمْ أَمْ لَمْ تُنذِرْهُمْ لَا يُؤْمِنُونَ","translationFa":"برای آنان یکسان است: چه انذارشان کنی یا نکنی، ایمان نمی‌آورند!"},{"number":11,"arabic":"إِنَّمَا تُنذِرُ مَنِ ٱتَّبَعَ ٱلذِّكْرَ وَخَشِىَ ٱلرَّحْمَٰنَ بِٱلْغَيْبِ ۖ فَبَشِّرْهُ بِمَغْفِرَةٍۢ وَأَجْرٍۢ كَرِيمٍ","translationFa":"تو فقط کسی را انذار می‌کنی که از این یادآوری (الهی) پیروی کند و از خداوند رحمان در نهان بترسد؛ چنین کسی را به آمرزش و پاداشی پرارزش بشارت ده!"},{"number":12,"arabic":"إِنَّا نَحْنُ نُحْىِ ٱلْمَوْتَىٰ وَنَكْتُبُ مَا قَدَّمُوا۟ وَءَاثَٰرَهُمْ ۚ وَكُلَّ شَىْءٍ أَحْصَيْنَٰهُ فِىٓ إِمَامٍۢ مُّبِينٍۢ","translationFa":"به یقین ما مردگان را زنده می‌کنیم و آنچه را از پیش فرستاده‌اند و تمام آثار آنها را می نویسیم؛ و همه چیز را در کتاب آشکار کننده‌ای برشمرده‌ایم!"},{"number":13,"arabic":"وَٱضْرِبْ لَهُم مَّثَلًا أَصْحَٰبَ ٱلْقَرْيَةِ إِذْ جَآءَهَا ٱلْمُرْسَلُونَ","translationFa":"و برای آنها، اصحاب قریه (انطاکیه) را مثال بزن هنگامی که فرستادگان خدا به سوی آنان آمدند؛"},{"number":14,"arabic":"إِذْ أَرْسَلْنَآ إِلَيْهِمُ ٱثْنَيْنِ فَكَذَّبُوهُمَا فَعَزَّزْنَا بِثَالِثٍۢ فَقَالُوٓا۟ إِنَّآ إِلَيْكُم مُّرْسَلُونَ","translationFa":"هنگامی که دو نفر از رسولان را بسوی آنها فرستادیم، امّا آنان رسولان (ما) را تکذیب کردند؛ پس برای تقویت آن دو، شخص سوّمی فر��تادیم، آنها همگی گفتند: «ما فرستادگان (خدا) به سوی شما هستیم!»"},{"number":15,"arabic":"قَالُوا۟ مَآ أَنتُمْ إِلَّا بَشَرٌۭ مِّثْلُنَا وَمَآ أَنزَلَ ٱلرَّحْمَٰنُ مِن شَىْءٍ إِنْ أَنتُمْ إِلَّا تَكْذِبُونَ","translationFa":"امّا آنان (در جواب) گفتند: «شما جز بشری همانند ما نیستید، و خداوند رحمان چیزی نازل نکرده، شما فقط دروغ می‌گویید!»"},{"number":16,"arabic":"قَالُوا۟ رَبُّنَا يَعْلَمُ إِنَّآ إِلَيْكُمْ لَمُرْسَلُونَ","translationFa":"(رسولان ما) گفتند: «پروردگار ما آگاه است که ما قطعاً فرستادگان (او) به سوی شما هستیم،"},{"number":17,"arabic":"وَمَا عَلَيْنَآ إِلَّا ٱلْبَلَٰغُ ٱلْمُبِينُ","translationFa":"و بر عهده ما چیزی جز ابلاغ آشکار نیست!»"},{"number":18,"arabic":"قَالُوٓا۟ إِنَّا تَطَيَّرْنَا بِكُمْ ۖ لَئِن لَّمْ تَنتَهُوا۟ لَنَرْجُمَنَّكُمْ وَلَيَمَسَّنَّكُم مِّنَّا عَذَابٌ أَلِيمٌۭ","translationFa":"آنان گفتند: «ما شما را به فال بد گرفته‌ایم (و وجود شما را شوم می‌دانیم)، و اگر (از این سخنان) دست برندارید شما را سنگسار خواهیم کرد و شکنجه دردناکی از ما به شما خواهد رسید!"},{"number":19,"arabic":"قَالُوا۟ طَٰٓئِرُكُم مَّعَكُمْ ۚ أَئِن ذُكِّرْتُم ۚ بَلْ أَنتُمْ قَوْمٌۭ مُّسْرِفُونَ","translationFa":"(رسولان) گفتند: «شومی شما از خودتان است اگر درست بیندیشید، بلکه شما گروهی اسرافکارید!»"},{"number":20,"arabic":"وَجَآءَ مِنْ أَقْصَا ٱلْمَدِينَةِ رَجُلٌۭ يَسْعَىٰ قَالَ يَٰقَوْمِ ٱتَّبِعُوا۟ ٱلْمُرْسَلِينَ","translationFa":"و مردی (با ایمان) از دورترین نقطه شهر با شتاب فرا رسید، گفت: «ای قوم من! از فرستادگان (خدا) پیروی کنید!"},{"number":21,"arabic":"ٱتَّبِعُوا۟ مَن لَّا يَسْـَٔلُكُمْ أَجْرًۭا وَهُم مُّهْتَدُونَ","translationFa":"از کسانی پیروی کنید که از شما مزدی نمی‌خواهند و خود هدایت یافته‌اند!"},{"number":22,"arabic":"وَمَا لِىَ لَآ أَعْبُدُ ٱلَّذِى فَطَرَنِى وَإِلَيْهِ تُرْجَعُونَ","translationFa":"من چرا کسی را پرستش نکنم که مرا آفریده، و همگی به سوی او بازگشت داده می‌شوید؟!"},{"number":23,"arabic":"ءَأَتَّخِذُ مِن دُونِهِۦٓ ءَالِهَةً إِن يُرِدْنِ ٱلرَّحْمَٰنُ بِضُرٍّۢ لَّا تُغْنِ عَنِّى شَفَٰعَتُهُمْ شَيْـًۭٔا وَلَا يُنقِذُونِ","translationFa":"آیا غیر از او معبودانی را انتخاب کنم که اگر خداوند رحمان بخواهد زیانی به من برساند، شفاعت آنها کمترین فایده‌ای برای من ندارد و مرا (از مجازات او) نجات نخواهند داد!"},{"number":24,"arabic":"إِنِّىٓ إِذًۭا لَّفِى ضَلَٰلٍۢ مُّبِينٍ","translationFa":"اگر چنین کنم، من در گمراهی آشکاری خواهم بود!"},{"number":25,"arabic":"إِنِّىٓ ءَامَنتُ بِرَبِّكُمْ فَٱسْمَعُونِ","translationFa":"(به همین دلیل) من به پروردگارتان ایمان آوردم؛ پس به سخنان من گوش فرا دهید!»"},{"number":26,"arabic":"قِيلَ ٱدْخُلِ ٱلْجَنَّةَ ۖ قَالَ يَٰلَيْتَ قَوْمِى يَعْلَمُونَ","translationFa":"(سرانجام او را شهید کردند و) به او گفته شد: «وارد بهشت شو!» گفت: «ای کاش قوم من می‌دانستند..."},{"number":27,"arabic":"بِمَا غَفَرَ لِى رَبِّى وَجَعَلَنِى مِنَ ٱلْمُكْرَمِينَ","translationFa":"که پروردگارم مرا آمرزیده و از گرامی‌داشتگان قرار داده است!»"},{"number":28,"arabic":"۞ وَمَآ أَنزَلْنَا عَلَىٰ قَوْمِهِۦ مِنۢ بَعْدِهِۦ مِن جُندٍۢ مِّنَ ٱلسَّمَآءِ وَمَا كُنَّا مُنزِلِينَ","translationFa":"و ما بعد از او بر قومش هیچ لشکری از آسمان نفرستادیم، و هرگز سنت ما بر این نبود؛"},{"number":29,"arabic":"إِن كَانَتْ إِلَّا صَيْحَةًۭ وَٰحِدَةًۭ فَإِذَا هُمْ خَٰمِدُونَ","translationFa":"(بلکه) فقط یک صیحه آسمانی بود، ناگهان همگی خاموش شدند!"},{"number":30,"arabic":"يَٰحَسْرَةً عَلَى ٱلْعِبَادِ ۚ مَا يَأْتِيهِم مِّن رَّسُولٍ إِلَّا كَانُوا۟ بِهِۦ يَسْتَهْزِءُونَ","translationFa":"افسوس بر این بندگان که هیچ پیامبری برای هدایت آنان نیامد مگر اینکه او را استهزا می‌کردند!"},{"number":31,"arabic":"أَلَمْ يَرَوْا۟ كَمْ أَهْلَكْنَا قَبْلَهُم مِّنَ ٱلْقُرُونِ أَنَّهُمْ إِلَيْهِمْ لَا يَرْجِعُونَ","translationFa":"آیا ندیدند چقدر از اقوام پیش از آنان را (بخاطر گناهانشان) هلاک کردیم، آنها هرگز به سوی ایشان بازنمی‌گردند (و زنده نمی‌شوند)!"},{"number":32,"arabic":"وَإِن كُلٌّۭ لَّمَّا جَمِيعٌۭ لَّدَيْنَا مُحْضَرُونَ","translationFa":"و همه آنان (روز قیامت) نزد ما احضار می‌شوند!"},{"number":33,"arabic":"وَءَايَةٌۭ لَّهُمُ ٱلْأَرْضُ ٱلْمَيْتَةُ أَحْيَيْنَٰهَا وَأَخْرَجْنَا مِنْهَا حَبًّۭا فَمِنْهُ يَأْكُلُونَ","translationFa":"زمین مرده برای آنها آیتی است، ما آن را زنده کردیم و دانه‌های (غذایی) از آن خارج ساختیم که از آن می‌خورند؛"},{"number":34,"arabic":"وَجَعَلْنَا فِيهَا جَنَّٰتٍۢ مِّن نَّخِيلٍۢ وَأَعْنَٰبٍۢ وَفَجَّرْنَا فِيهَا مِنَ ٱلْعُيُونِ","translationFa":"و در آن باغهایی از نخلها و انگورها قرار دادیم و چشمه‌هایی از آن جاری ساختیم،"},{"number":35,"arabic":"لِيَأْكُلُوا۟ مِن ثَمَرِهِۦ وَمَا عَمِلَتْهُ أَيْدِيهِمْ ۖ أَفَلَا يَشْكُرُونَ","translationFa":"تا از میوه آن بخورند در حالی که دست آنان هیچ دخالتی در ساختن آن نداشته است! آیا شکر خدا را بجا نمی‌آورند؟!"},{"number":36,"arabic":"سُبْحَٰنَ ٱلَّذِى خَلَقَ ٱلْأَزْوَٰجَ كُلَّهَا مِمَّا تُنۢبِتُ ٱلْأَرْضُ وَمِنْ أَنفُسِهِمْ وَمِمَّا لَا يَعْلَمُونَ","translationFa":"منزه است کسی که تمام زوجها را آفرید، از آنچه زمین می‌رویاند، و از خودشان، و از آنچه نمی‌دانند!"},{"number":37,"arabic":"وَءَايَةٌۭ لَّهُمُ ٱلَّيْلُ نَسْلَخُ مِنْهُ ٱلنَّهَارَ فَإِذَا هُم مُّظْلِمُونَ","translationFa":"شب (نیز) برای آنها نشانه‌ای است (از عظمت خدا)؛ ما روز را از آن برمی‌گیریم، ناگهان تاریکی آنان را فرا می‌گیرد!"},{"number":38,"arabic":"وَٱلشَّمْسُ تَجْرِى لِمُسْتَقَرٍّۢ لَّهَا ۚ ذَٰلِكَ تَقْدِيرُ ٱلْعَزِيزِ ٱلْعَلِيمِ","translationFa":"و خورشید (نیز برای آنها آیتی است) که پیوسته بسوی قرارگاهش در حرکت است؛ این تقدیر خداوند قادر و داناست."},{"number":39,"arabic":"وَٱلْقَمَرَ قَدَّرْنَٰهُ مَنَازِلَ حَتَّىٰ عَادَ كَٱلْعُرْجُونِ ٱلْقَدِيمِ","translationFa":"و برای ماه منزلگاه‌هایی قرار دادیم، (و هنگامی که این منازل را طی کرد) سرانجام بصورت «شاخه کهنه قوسی شکل و زرد رنگ خرما» در می‌آید."},{"number":40,"arabic":"لَا ٱلشَّمْسُ يَنۢبَغِى لَهَآ أَن تُدْرِكَ ٱلْقَمَرَ وَلَا ٱلَّيْلُ سَابِقُ ٱلنَّهَارِ ۚ وَكُلٌّۭ فِى فَلَكٍۢ يَسْبَحُونَ","translationFa":"نه خورشید را سزاست که به ماه رسد، و نه شب بر روز پیشی می‌گیرد؛ و هر کدام در مسیر خود شناورند."},{"number":41,"arabic":"وَءَايَةٌۭ لَّهُمْ أَنَّا حَمَلْنَا ذُرِّيَّتَهُمْ فِى ٱلْفُلْكِ ٱلْمَشْحُونِ","translationFa":"نشانه‌ای (دیگر از عظمت پروردگار) برای آنان است که ما فرزندانشان را در کشتیهایی پر (از وسایل و بارها) حمل کردیم."},{"number":42,"arabic":"وَخَلَقْنَا لَهُم مِّن مِّثْلِهِۦ مَا يَرْكَبُونَ","translationFa":"و برای آنها مرکبهای دیگری همانند آن آفریدیم."},{"number":43,"arabic":"وَإِن نَّشَأْ نُغْرِقْهُمْ فَلَا صَرِيخَ لَهُمْ وَلَا هُمْ يُنقَذُونَ","translationFa":"و اگر بخواهیم آنها را غرق می‌کنیم بطور�� که نه فریادرسی داشته باشند و نه نجات داده شوند!"},{"number":44,"arabic":"إِلَّا رَحْمَةًۭ مِّنَّا وَمَتَٰعًا إِلَىٰ حِينٍۢ","translationFa":"مگر اینکه رحمت ما شامل حال آنان شود، و تا زمان معیّنی از این زندگی بهره گیرند!"},{"number":45,"arabic":"وَإِذَا قِيلَ لَهُمُ ٱتَّقُوا۟ مَا بَيْنَ أَيْدِيكُمْ وَمَا خَلْفَكُمْ لَعَلَّكُمْ تُرْحَمُونَ","translationFa":"و هرگاه به آنها گفته شود: «از آنچه پیش رو و پشت سر شماست [= از عذابهای الهی‌] بترسید تا مشمول رحمت الهی شوید!» (اعتنا نمی‌کنند)."},{"number":46,"arabic":"وَمَا تَأْتِيهِم مِّنْ ءَايَةٍۢ مِّنْ ءَايَٰتِ رَبِّهِمْ إِلَّا كَانُوا۟ عَنْهَا مُعْرِضِينَ","translationFa":"و هیچ آیه‌ای از آیات پروردگارشان برای آنها نمی‌آید مگر اینکه از آن روی‌گردان می شوند."},{"number":47,"arabic":"وَإِذَا قِيلَ لَهُمْ أَنفِقُوا۟ مِمَّا رَزَقَكُمُ ٱللَّهُ قَالَ ٱلَّذِينَ كَفَرُوا۟ لِلَّذِينَ ءَامَنُوٓا۟ أَنُطْعِمُ مَن لَّوْ يَشَآءُ ٱللَّهُ أَطْعَمَهُۥٓ إِنْ أَنتُمْ إِلَّا فِى ضَلَٰلٍۢ مُّبِينٍۢ","translationFa":"و هنگامی که به آنان گفته شود: «از آنچه خدا به شما روزی کرده انفاق کنید!»، کافران به مؤمنان می‌گویند: «آیا ما کسی را اطعام کنیم که اگر خدا می‌خواست او را اطعام می‌کرد؟! (پس خدا خواسته است او گرسنه باشد)، شما فقط در گمراهی آشکارید»!"},{"number":48,"arabic":"وَيَقُولُونَ مَتَىٰ هَٰذَا ٱلْوَعْدُ إِن كُنتُمْ صَٰدِقِينَ","translationFa":"آنها می‌گویند: «اگر راست می‌گویید، این وعده (قیامت) کی خواهد بود؟!"},{"number":49,"arabic":"مَا يَنظُرُونَ إِلَّا صَيْحَةًۭ وَٰحِدَةًۭ تَأْخُذُهُمْ وَهُمْ يَخِصِّمُونَ","translationFa":"(امّا) جز این انتظار نمی‌کشند که یک صیحه عظیم (آسمانی) آنها را فراگیرد، در حالی که مشغول جدال (در امور دنیا) هستند."},{"number":50,"arabic":"فَلَا يَسْتَطِيعُونَ تَوْصِيَةًۭ وَلَآ إِلَىٰٓ أَهْلِهِمْ يَرْجِعُونَ","translationFa":"(چنان غافلگیر می‌شوند که حتّی) نمی‌توانند وصیّتی کنند یا به سوی خانواده خود بازگردند!"},{"number":51,"arabic":"وَنُفِخَ فِى ٱلصُّورِ فَإِذَا هُم مِّنَ ٱلْأَجْدَاثِ إِلَىٰ رَبِّهِمْ يَنسِلُونَ","translationFa":"(بار دیگر) در «صور» دمیده می‌شود، ناگهان آنها از قبرها، شتابان به سوی (دادگاه) پروردگارشان می‌روند!"},{"number":52,"arabic":"قَالُوا۟ يَٰوَيْلَنَا مَنۢ بَعَثَنَا مِن مَّرْقَدِنَا ۜ ۗ هَٰذَا مَا وَعَدَ ٱلرَّحْمَٰنُ وَصَدَقَ ٱلْمُرْسَلُونَ","translationFa":"می‌گویند: «ای وای بر ما! چه کسی ما را از خوابگاهمان برانگیخت؟! (آری) این همان است که خداوند رحمان وعده داده، و فرستادگان (او) راست گفتند!»"},{"number":53,"arabic":"إِن كَانَتْ إِلَّا صَيْحَةًۭ وَٰحِدَةًۭ فَإِذَا هُمْ جَمِيعٌۭ لَّدَيْنَا مُحْضَرُونَ","translationFa":"صیحه واحدی بیش نیست، (فریادی عظیم برمی‌خیزد) ناگهان همگی نزد ما احضار می‌شوند!"},{"number":54,"arabic":"فَٱلْيَوْمَ لَا تُظْلَمُ نَفْسٌۭ شَيْـًۭٔا وَلَا تُجْزَوْنَ إِلَّا مَا كُنتُمْ تَعْمَلُونَ","translationFa":"(و به آنها گفته می‌شود:) امروز به هیچ کس ذرّه‌ای ستم نمی‌شود، و جز آنچه را عمل می‌کردید جزا داده نمی‌شوید!"},{"number":55,"arabic":"إِنَّ أَصْحَٰبَ ٱلْجَنَّةِ ٱلْيَوْمَ فِى شُغُلٍۢ فَٰكِهُونَ","translationFa":"بهشتیان، امروز به نعمتهای خدا مشغول و مسرورند."},{"number":56,"arabic":"هُمْ وَأَزْوَٰجُهُمْ فِى ظِلَٰلٍ عَلَى ٱلْأَرَآئِكِ مُتَّكِـُٔونَ","translationFa":"آنها و همسرانشان در سایه‌های (قصرها و درختان بهشتی) بر تختها تکیه زده‌اند."},{"number":57,"arabic":"لَهُمْ فِيهَا فَٰكِهَةٌۭ وَلَهُم مَّا يَدَّعُونَ","translationFa":"برای آنها در بهشت میوه بسیار لذّت‌بخشی است، و هر چه بخواهند در اختیار آنان خواهد بود!"},{"number":58,"arabic":"سَلَٰمٌۭ قَوْلًۭا مِّن رَّبٍّۢ رَّحِيمٍۢ","translationFa":"بر آنها سلام (و درود الهی) است؛ این سخنی است از سوی پروردگاری مهربان!"},{"number":59,"arabic":"وَٱمْتَٰزُوا۟ ٱلْيَوْمَ أَيُّهَا ٱلْمُجْرِمُونَ","translationFa":"(و به آنها می‌گویند:) جدا شوید امروز ای گنهکاران!"},{"number":60,"arabic":"۞ أَلَمْ أَعْهَدْ إِلَيْكُمْ يَٰبَنِىٓ ءَادَمَ أَن لَّا تَعْبُدُوا۟ ٱلشَّيْطَٰنَ ۖ إِنَّهُۥ لَكُمْ عَدُوٌّۭ مُّبِينٌۭ","translationFa":"آیا با شما عهد نکردم ای فرزندان آدم که شیطان را نپرستید، که او برای شما دشمن آشکاری است؟!"},{"number":61,"arabic":"وَأَنِ ٱعْبُدُونِى ۚ هَٰذَا صِرَٰطٌۭ مُّسْتَقِيمٌۭ","translationFa":"و اینکه مرا بپرستید که راه مستقیم این است؟!"},{"number":62,"arabic":"وَلَقَدْ أَضَلَّ مِنكُمْ جِبِلًّۭا كَثِيرًا ۖ أَفَلَمْ تَكُونُوا۟ تَعْقِلُونَ","translationFa":"او گروه زیادی از شما را گمراه کرد، آیا اندیشه نکردید؟!"},{"number":63,"arabic":"هَٰذِهِۦ جَهَنَّمُ ٱلَّتِى كُنتُمْ تُوعَدُونَ","translationFa":"این همان دوزخی است که به شما وعده داده می‌شد!"},{"number":64,"arabic":"ٱصْلَوْهَا ٱلْيَوْمَ بِمَا كُنتُمْ تَكْفُرُونَ","translationFa":"امروز وارد آن شوید و به خاطر کفری که داشتید به آتش آن بسوزید!"},{"number":65,"arabic":"ٱلْيَوْمَ نَخْتِمُ عَلَىٰٓ أَفْوَٰهِهِمْ وَتُكَلِّمُنَآ أَيْدِيهِمْ وَتَشْهَدُ أَرْجُلُهُم بِمَا كَانُوا۟ يَكْسِبُونَ","translationFa":"امروز بر دهانشان مُهر می‌نهیم، و دستهایشان با ما سخن می‌گویند و پاهایشان کارهایی را که انجام می‌دادند شهادت می‌دهند!"},{"number":66,"arabic":"وَلَوْ نَشَآءُ لَطَمَسْنَا عَلَىٰٓ أَعْيُنِهِمْ فَٱسْتَبَقُوا۟ ٱلصِّرَٰطَ فَأَنَّىٰ يُبْصِرُونَ","translationFa":"و اگر بخواهیم چشمانشان را محو کنیم؛ سپس برای عبور از راه، می‌خواهند بر یکدیگر پیشی بگیرند، امّا چگونه می‌توانند ببینند؟!"},{"number":67,"arabic":"وَلَوْ نَشَآءُ لَمَسَخْنَٰهُمْ عَلَىٰ مَكَانَتِهِمْ فَمَا ٱسْتَطَٰعُوا۟ مُضِيًّۭا وَلَا يَرْجِعُونَ","translationFa":"و اگر بخواهیم آنها را در جای خود مسخ می‌کنیم (و به مجسمه‌هایی بی‌روح مبدّل می‌سازیم) تا نتوانند راه خود را ادامه دهند یا به عقب برگردند!"},{"number":68,"arabic":"وَمَن نُّعَمِّرْهُ نُنَكِّسْهُ فِى ٱلْخَلْقِ ۖ أَفَلَا يَعْقِلُونَ","translationFa":"هر کس را طول عمر دهیم، در آفرینش واژگونه‌اش می‌کنیم (و به ناتوانی کودکی باز می‌گردانیم)؛ آیا اندیشه نمی‌کنند؟!"},{"number":69,"arabic":"وَمَا عَلَّمْنَٰهُ ٱلشِّعْرَ وَمَا يَنۢبَغِى لَهُۥٓ ۚ إِنْ هُوَ إِلَّا ذِكْرٌۭ وَقُرْءَانٌۭ مُّبِينٌۭ","translationFa":"ما هرگز شعر به او [= پیامبر] نیاموختیم، و شایسته او نیست (شاعر باشد)؛ این (کتاب آسمانی) فقط ذکر و قرآن مبین است!"},{"number":70,"arabic":"لِّيُنذِرَ مَن كَانَ حَيًّۭا وَيَحِقَّ ٱلْقَوْلُ عَلَى ٱلْكَٰفِرِينَ","translationFa":"تا افرادی را که زنده‌اند بیم دهد (و بر کافران اتمام حجّت شود) و فرمان عذاب بر آنان مسلّم گردد!"},{"number":71,"arabic":"أَوَلَمْ يَرَوْا۟ أَنَّا خَلَقْنَا لَهُم مِّمَّا عَمِلَتْ أَيْدِينَآ أَنْعَٰمًۭا فَهُمْ لَهَا مَٰلِكُونَ","translationFa":"آیا ندیدند که از آنچه با قدرت خود به عمل آورده‌ایم چهارپایانی برای آنان آفریدیم که آنان مالک آن هستند؟!"},{"number":72,"arabic":"وَذَلَّلْنَٰهَا لَهُمْ فَمِنْهَا رَكُوبُهُمْ وَمِنْهَا يَأْكُلُونَ","translationFa":"و آنها را رام ایشان ساختیم، هم مرکب آنان از آن است و هم از آن تغذیه می‌کنند؛"},{"number":73,"arabic":"وَلَهُمْ فِيهَا مَنَٰفِعُ وَمَشَارِبُ ۖ أَفَلَا يَشْكُرُونَ","translationFa":"و برای آنان بهره‌های دیگری در آن (حیوانات) است و نوشیدنیهائی گوارا؛ آیا با این حال شکرگزاری نمی‌کنند؟!"},{"number":74,"arabic":"وَٱتَّخَذُوا۟ مِن دُونِ ٱللَّهِ ءَالِهَةًۭ لَّعَلَّهُمْ يُنصَرُونَ","translationFa":"آنان غیر از خدا معبودانی برای خویش برگزیدند به این امید که یاری شوند!"},{"number":75,"arabic":"لَا يَسْتَطِيعُونَ نَصْرَهُمْ وَهُمْ لَهُمْ جُندٌۭ مُّحْضَرُونَ","translationFa":"ولی آنها قادر به یاری ایشان نیستند، و این (عبادت‌کنندگان در قیامت) لشکری برای آنها خواهند بود که در آتش دوزخ احضار می‌شوند!"},{"number":76,"arabic":"فَلَا يَحْزُنكَ قَوْلُهُمْ ۘ إِنَّا نَعْلَمُ مَا يُسِرُّونَ وَمَا يُعْلِنُونَ","translationFa":"پس سخنانشان تو را غمگین نسازد، ما آنچه را پنهان می‌دارند و آنچه را آشکار می‌کنند می‌دانیم!"},{"number":77,"arabic":"أَوَلَمْ يَرَ ٱلْإِنسَٰنُ أَنَّا خَلَقْنَٰهُ مِن نُّطْفَةٍۢ فَإِذَا هُوَ خَصِيمٌۭ مُّبِينٌۭ","translationFa":"آیا انسان نمی‌داند که ما او را از نطفه‌ای بی‌ارزش آفریدیم؟! و او (چنان صاحب قدرت و شعور و نطق شد که) به مخاصمه آشکار (با ما) برخاست!"},{"number":78,"arabic":"وَضَرَبَ لَنَا مَثَلًۭا وَنَسِىَ خَلْقَهُۥ ۖ قَالَ مَن يُحْىِ ٱلْعِظَٰمَ وَهِىَ رَمِيمٌۭ","translationFa":"و برای ما مثالی زد و آفرینش خود را فراموش کرد و گفت: «چه کسی این استخوانها را زنده می‌کند در حالی که پوسیده است؟!»"},{"number":79,"arabic":"قُلْ يُحْيِيهَا ٱلَّذِىٓ أَنشَأَهَآ أَوَّلَ مَرَّةٍۢ ۖ وَهُوَ بِكُلِّ خَلْقٍ عَلِيمٌ","translationFa":"بگو: «همان کسی آن را زنده می‌کند که نخستین بار آن را آفرید؛ و او به هر مخلوقی داناست!"},{"number":80,"arabic":"ٱلَّذِى جَعَلَ لَكُم مِّنَ ٱلشَّجَرِ ٱلْأَخْضَرِ نَارًۭا فَإِذَآ أَنتُم مِّنْهُ تُوقِدُونَ","translationFa":"همان کسی که برای شما از درخت سبز، آتش آفرید و شما بوسیله آن، آتش می‌افروزید!»"},{"number":81,"arabic":"أَوَلَيْسَ ٱلَّذِى خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ بِقَٰدِرٍ عَلَىٰٓ أَن يَخْلُقَ مِثْلَهُم ۚ بَلَىٰ وَهُوَ ٱلْخَلَّٰقُ ٱلْعَلِيمُ","translationFa":"آیا کسی که آسمانها و زمین را آفرید، نمی‌تواند همانند آنان [= انسانهای خاک شده‌] را بیافریند؟! آری (می‌تواند)، و او آفریدگار داناست!"},{"number":82,"arabic":"إِنَّمَآ أَمْرُهُۥٓ إِذَآ أَرَادَ شَيْـًٔا أَن يَقُولَ لَهُۥ كُن فَيَكُونُ","translationFa":"فرمان او چنین است که هرگاه چیزی را اراده کند، تنها به آن می‌گوید: «موجود باش!»، آن نیز بی‌درنگ موجود می‌شود!"},{"number":83,"arabic":"فَسُبْحَٰنَ ٱلَّذِى بِيَدِهِۦ مَلَكُوتُ كُلِّ شَىْءٍۢ وَإِلَيْهِ تُرْجَعُونَ","translationFa":"پس منزّه است خداوندی که مالکیّت و حاکمیّت همه چیز در دست اوست؛ و شما را به سوی او بازمی‌گردانند!"}],"37":[{"number":1,"arabic":"بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ وَٱلصَّٰٓفَّٰتِ صَفًّۭا","translationFa":"سوگند به (فرشتگان) صف‌کشیده (و منظّم)"},{"number":2,"arabic":"فَٱلزَّٰجِرَٰتِ زَجْرًۭا","translationFa":"و به نهی‌کنندگان و (بازدارندگان)"},{"number":3,"arabic":"فَٱلتَّٰلِيَٰتِ ذِكْرًا","translationFa":"و تلاوت‌کنندگان پیاپی آیات الهی..."},{"number":4,"arabic":"إِنَّ إِلَٰهَكُمْ لَوَٰحِدٌۭ","translationFa":"که معبود شما یگانه است؛"},{"number":5,"arabic":"رَّبُّ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَمَا بَيْنَهُمَا وَرَبُّ ٱلْمَشَٰرِقِ","translationFa":"پروردگار آسمانها و زمین و آنچه میان آنهاست، و پروردگار مشرقها!"},{"number":6,"arabic":"إِنَّا زَيَّنَّا ٱلسَّمَآءَ ٱلدُّنْيَا بِزِينَةٍ ٱلْكَوَاكِبِ","translationFa":"ما آسمان نزدیک [= پایین‌] را با ستارگان آراستیم،"},{"number":7,"arabic":"وَحِفْظًۭا مِّن كُلِّ شَيْطَٰنٍۢ مَّارِدٍۢ","translationFa":"تا آن را از هر شیطان خبیثی حفظ کنیم!"},{"number":8,"arabic":"لَّا يَسَّمَّعُونَ إِلَى ٱلْمَلَإِ ٱلْأَعْلَىٰ وَيُقْذَفُونَ مِن كُلِّ جَانِبٍۢ","translationFa":"آنها نمی‌توانند به (سخنان) فرشتگان عالم بالا گوش فرادهند، (و هرگاه چنین کنند) از هر سو هدف قرارمی‌گیرند!"},{"number":9,"arabic":"دُحُورًۭا ۖ وَلَهُمْ عَذَابٌۭ وَاصِبٌ","translationFa":"آنها به شدّت به عقب رانده می‌شوند؛ و برای آنان مجازاتی دائم است!"},{"number":10,"arabic":"إِلَّا مَنْ خَطِفَ ٱلْخَطْفَةَ فَأَتْبَعَهُۥ شِهَابٌۭ ثَاقِبٌۭ","translationFa":"مگر آنها که در لحظه‌ای کوتاه برای استراق سمع به آسمان نزدیک شوند، که «شهاب ثاقب» آنها را تعقیب می‌کند!"},{"number":11,"arabic":"فَٱسْتَفْتِهِمْ أَهُمْ أَشَدُّ خَلْقًا أَم مَّنْ خَلَقْنَآ ۚ إِنَّا خَلَقْنَٰهُم مِّن طِينٍۢ لَّازِبٍۭ","translationFa":"از آنان بپرس: «آیا آفرینش (و معاد) آنان سخت‌تر است یا آفرینش فرشتگان (و آسمانها و زمین)؟! ما آنان را از گل چسبنده‌ای آفریدیم!"},{"number":12,"arabic":"بَلْ عَجِبْتَ وَيَسْخَرُونَ","translationFa":"تو از انکارشان تعجّب می‌کنی، ولی آنها مسخره می‌کنند!"},{"number":13,"arabic":"وَإِذَا ذُكِّرُوا۟ لَا يَذْكُرُونَ","translationFa":"و هنگامی که به آنان تذکّر داده شود، هرگز متذکّر نمی‌شوند!"},{"number":14,"arabic":"وَإِذَا رَأَوْا۟ ءَايَةًۭ يَسْتَسْخِرُونَ","translationFa":"و هنگامی که معجزه‌ای را ببینند، دیگران را نیز به استهزا دعوت می‌کنند!"},{"number":15,"arabic":"وَقَالُوٓا۟ إِنْ هَٰذَآ إِلَّا سِحْرٌۭ مُّبِينٌ","translationFa":"و می‌گویند: «این فقط سحری آشکار است!"},{"number":16,"arabic":"أَءِذَا مِتْنَا وَكُنَّا تُرَابًۭا وَعِظَٰمًا أَءِنَّا لَمَبْعُوثُونَ","translationFa":"آیا هنگامی که ما مُردیم و به خاک و استخوان مبدّل شدیم، بار دیگر برانگیخته خواهیم شد؟!"},{"number":17,"arabic":"أَوَءَابَآؤُنَا ٱلْأَوَّلُونَ","translationFa":"یا پدران نخستین ما (بازمی‌گردند)؟!»"},{"number":18,"arabic":"قُلْ نَعَمْ وَأَنتُمْ دَٰخِرُونَ","translationFa":"بگو: «آری، همه شما زنده می‌شوید در حالی که خوار و کوچک خواهید بود!"},{"number":19,"arabic":"فَإِنَّمَا هِىَ زَجْرَةٌۭ وَٰحِدَةٌۭ فَإِذَا هُمْ يَنظُرُونَ","translationFa":"تنها یک صیحه عظیم واقع می‌شود، ناگهان همه (از قبرها برمی‌خیزند و) نگاه می‌کنند!"},{"number":20,"arabic":"وَقَالُوا۟ يَٰوَيْلَنَا هَٰذَا يَوْمُ ٱلدِّينِ","translationFa":"و می‌گویند: «ای وای بر ما، این روز جزاست!»"},{"number":21,"arabic":"هَٰذَا يَوْمُ ٱلْفَصْلِ ٱلَّذِى كُنتُم بِهِۦ تُكَذِّبُونَ","translationFa":"(آری) این همان روز جدایی (حقّ از باطل) است که شما آن را تکذیب می‌کردید!"},{"number":22,"arabic":"۞ ٱحْشُرُوا۟ ٱلَّذِينَ ظَلَمُوا۟ وَأَزْوَٰجَهُمْ وَمَا كَانُوا۟ يَعْبُدُونَ","translationFa":"(در این هنگام به فرشتگان دستور داده می‌شود:) ظالمان و همردیفانشان و آنچه را می‌پرستیدند..."},{"number":23,"arabic":"مِن دُونِ ٱللَّهِ فَٱهْدُوهُمْ إِلَىٰ صِرَٰطِ ٱلْجَحِيمِ","translationFa":"(آری آنچه را) جز خدا می‌پرستیدند جمع کنید و بسوی راه دوزخ هدایتشان کنید!"},{"number":24,"arabic":"وَقِفُوهُمْ ۖ إِنَّهُم مَّسْـُٔولُونَ","translationFa":"آنها را نگهدارید که باید بازپرسی شوند!"},{"number":25,"arabic":"مَا لَكُمْ لَا تَنَاصَرُونَ","translationFa":"شما را چه شده که از هم یاری نمی‌طلبید؟!"},{"number":26,"arabic":"بَلْ هُمُ ٱلْيَوْمَ مُسْتَسْلِمُونَ","translationFa":"ولی آنان در آن روز تسلیم قدرت خداوندند!"},{"number":27,"arabic":"وَأَقْبَلَ بَعْضُهُمْ عَلَىٰ بَعْضٍۢ يَتَسَآءَلُونَ","translationFa":"(و در این حال) رو به یکدیگر کرده و از هم می‌پرسند..."},{"number":28,"arabic":"قَالُوٓا۟ إِنَّكُمْ كُنتُمْ تَأْتُونَنَا عَنِ ٱلْيَمِينِ","translationFa":"گروهی (می‌گویند: «شما رهبران گمراهی بودید که به ظاهر) از طریق خیرخواهی و نیکی وارد شدید امّا جز فریب چیزی در کارتان نبود)!»"},{"number":29,"arabic":"قَالُوا۟ بَل لَّمْ تَكُونُوا۟ مُؤْمِنِينَ","translationFa":"(آنها در جواب) می‌گویند: «شما خودتان اهل ایمان نبودید (تقصیر ما چیست)؟!"},{"number":30,"arabic":"وَمَا كَانَ لَنَا عَلَيْكُم مِّن سُلْطَٰنٍۭ ۖ بَلْ كُنتُمْ قَوْمًۭا طَٰغِينَ","translationFa":"ما هیچ گونه سلطه‌ای بر شما نداشتیم، بلکه شما خود قومی طغیانگر بودید!"},{"number":31,"arabic":"فَحَقَّ عَلَيْنَا قَوْلُ رَبِّنَآ ۖ إِنَّا لَذَآئِقُونَ","translationFa":"اکنون فرمان پروردگارمان بر همه ما مسلّم شده، و همگی از عذاب او می‌چشیم!"},{"number":32,"arabic":"فَأَغْوَيْنَٰكُمْ إِنَّا كُنَّا غَٰوِينَ","translationFa":"ما شما را گمراه کردیم، همان گونه که خود گمراه بودیم!"},{"number":33,"arabic":"فَإِنَّهُمْ يَوْمَئِذٍۢ فِى ٱلْعَذَابِ مُشْتَرِكُونَ","translationFa":"(آری) همه آنها [= پیشوایان و پیروان گمراه‌] در آن روز در عذاب الهی مشترکند!"},{"number":34,"arabic":"إِنَّا كَذَٰلِكَ نَفْعَلُ بِٱلْمُجْرِمِينَ","translationFa":"ما این گونه با مجرمان رفتار می‌کنیم!"},{"number":35,"arabic":"إِنَّهُمْ كَانُوٓا۟ إِذَا قِيلَ لَهُمْ لَآ إِلَٰهَ إِلَّا ٱللَّهُ يَسْتَكْبِرُونَ","translationFa":"چرا که وقتی به آنها گفته می‌شد: «معبودی جز خدا وجود ندارد»، تکبّر و سرکشی می‌کردند..."},{"number":36,"arabic":"وَيَقُولُونَ أَئِنَّا لَتَارِكُوٓا۟ ءَالِهَتِنَا لِشَاعِرٍۢ مَّجْنُونٍۭ","translationFa":"و پیوسته می‌گفتند: «آیا ما معبودان خود را بخاطر شاعری دیوانه رها کنیم؟!»"},{"number":37,"arabic":"بَلْ جَآءَ بِٱلْحَقِّ وَصَدَّقَ ٱلْمُرْسَلِينَ","translationFa":"چنین نیست، او حقّ را آورده و پیامبران پیشین را تصدیق کرده است!"},{"number":38,"arabic":"إِنَّكُمْ لَذَآئِقُوا۟ ٱلْعَذَابِ ٱلْأَلِيمِ","translationFa":"اما شما (مستکبران کوردل) بطور مسلّم عذاب دردناک (الهی) را خواهید چشید!"},{"number":39,"arabic":"وَمَا تُجْزَوْنَ إِلَّا مَا كُنتُمْ تَعْمَلُونَ","translationFa":"و جز به آنچه انجام می‌دادید کیفر داده نمی‌شوید،"},{"number":40,"arabic":"إِلَّا عِبَادَ ٱللَّهِ ٱلْمُخْلَصِينَ","translationFa":"جز بندگان مخلص خدا (که از این کیفرها برکنارند)!"},{"number":41,"arabic":"أُو۟لَٰٓئِكَ لَهُمْ رِزْقٌۭ مَّعْلُومٌۭ","translationFa":"برای آنان [= بندگان مخلص‌] روزی معیّن و ویژه‌ای است،"},{"number":42,"arabic":"فَوَٰكِهُ ۖ وَهُم مُّكْرَمُونَ","translationFa":"میوه‌ها (ی گوناگون پر ارزش)، و آنها گرامی داشته می‌شوند..."},{"number":43,"arabic":"فِى جَنَّٰتِ ٱلنَّعِيمِ","translationFa":"در باغهای پر نعمت بهشت؛"},{"number":44,"arabic":"عَلَىٰ سُرُرٍۢ مُّتَقَٰبِلِينَ","translationFa":"در حالی که بر تختها رو به روی یکدیگر تکیه زده‌اند،"},{"number":45,"arabic":"يُطَافُ عَلَيْهِم بِكَأْسٍۢ مِّن مَّعِينٍۭ","translationFa":"و گرداگردشان قدحهای لبریز از شراب طهور را می‌گردانند؛"},{"number":46,"arabic":"بَيْضَآءَ لَذَّةٍۢ لِّلشَّٰرِبِينَ","translationFa":"شرابی سفید و درخشنده، و لذّتبخش برای نوشندگان؛"},{"number":47,"arabic":"لَا فِيهَا غَوْلٌۭ وَلَا هُمْ عَنْهَا يُنزَفُونَ","translationFa":"شرابی که نه در آن مایه تباهی عقل است و نه از آن مست می‌شوند!"},{"number":48,"arabic":"وَعِندَهُمْ قَٰصِرَٰتُ ٱلطَّرْفِ عِينٌۭ","translationFa":"و نزد آنها همسرانی زیبا چشم است که جز به شوهران خود عشق نمی‌ورزند."},{"number":49,"arabic":"كَأَنَّهُنَّ بَيْضٌۭ مَّكْنُونٌۭ","translationFa":"گویی از (لطافت و سفیدی) همچون تخم‌مرغهایی هستند که (در زیر بال و پر مرغ) پنهان مانده (و دست انسانی هرگز آن را لمس نکرده است)!"},{"number":50,"arabic":"فَأَقْبَلَ بَعْضُهُمْ عَلَىٰ بَعْضٍۢ يَتَسَآءَلُونَ","translationFa":"(در حالی که آنها غرق گفتگو هستند) بعضی رو به بعضی دیگر کرده می‌پرسند..."},{"number":51,"arabic":"قَالَ قَآئِلٌۭ مِّنْهُمْ إِنِّى كَانَ لِى قَرِينٌۭ","translationFa":"کسی از آنها می‌گوید: «من همنشینی داشتم..."},{"number":52,"arabic":"يَقُولُ أَءِنَّكَ لَمِنَ ٱلْمُصَدِّقِينَ","translationFa":"که پیوسته می‌گفت: آیا (به راستی) تو این سخن را باور کرده‌ای..."},{"number":53,"arabic":"أَءِذَا مِتْنَا وَكُنَّا تُرَابًۭا وَعِظَٰمًا أَءِنَّا لَمَدِينُونَ","translationFa":"که وقتی ما مُردیم و به خاک و استخوان مبدّل شدیم، (بار دیگر) زنده می‌شویم و جزا داده خواهیم شد؟!»"},{"number":54,"arabic":"قَالَ هَلْ أَنتُم مُّطَّلِعُونَ","translationFa":"(سپس) می‌گوید: «آیا شما می‌توانید از او خبری بگیرید؟»"},{"number":55,"arabic":"فَٱطَّلَعَ فَرَءَاهُ فِى سَوَآءِ ٱلْجَحِيمِ","translationFa":"اینجاست که نگاهی می‌کند، ناگهان او را در میان دوزخ می‌بیند."},{"number":56,"arabic":"قَالَ تَٱللَّهِ إِن كِدتَّ لَتُرْدِينِ","translationFa":"می‌گوید: «به خدا سوگند نزدیک بود مرا (نیز) به هلاکت بکشانی!"},{"number":57,"arabic":"وَلَوْلَا نِعْمَةُ رَبِّى لَكُنتُ مِنَ ٱلْمُحْضَرِينَ","translationFa":"و اگر نعمت پروردگارم نبود، من نیز از احضارشدگان (در دوزخ) بودم!"},{"number":58,"arabic":"أَفَمَا نَحْنُ بِمَيِّتِينَ","translationFa":"(سپس به یاران خود می‌گوید: ای دوستان!) آیا ما هرگز نمی‌میریم (و در بهشت جاودانه خواهیم بود)،"},{"number":59,"arabic":"إِلَّا مَوْتَتَنَا ٱلْأُولَىٰ وَمَا نَحْنُ بِمُعَذَّبِينَ","translationFa":"و جز همان مرگ اول، مرگی به سراغ ما نخواهد آمد، و ما هرگز عذاب نخواهیم شد."},{"number":60,"arabic":"إِنَّ هَٰذَا لَهُوَ ٱلْفَوْزُ ٱلْعَظِيمُ","translationFa":"راستی این همان پیروزی بزرگ است!"},{"number":61,"arabic":"لِمِثْلِ هَٰذَا فَلْيَعْمَلِ ٱلْعَٰمِلُونَ","translationFa":"آری، برای مثل این، باید عمل‌کنندگان عمل کنند!"},{"number":62,"arabic":"أَذَٰلِكَ خَيْرٌۭ نُّزُلًا أَمْ شَجَرَةُ ٱلزَّقُّومِ","translationFa":"آیا این (نعمتهای جاویدان بهشتی) بهتر است یا درخت (نفرت‌انگیز) زقّوم؟!"},{"number":63,"arabic":"إِنَّا جَعَلْنَٰهَا فِتْنَةًۭ لِّلظَّٰلِمِينَ","translationFa":"ما آن را مایه درد و رنج ظالمان قرار دادیم!"},{"number":64,"arabic":"إِنَّهَا شَجَرَةٌۭ تَخْرُجُ فِىٓ أَصْلِ ٱلْجَحِيمِ","translationFa":"آن درختی است که از قعر جهنّم می‌روید!"},{"number":65,"arabic":"طَلْعُهَا كَأَنَّهُۥ رُءُوسُ ٱلشَّيَٰطِينِ","translationFa":"شکوفه آن مانند سرهای شیاطین است!"},{"number":66,"arabic":"فَإِنَّهُمْ لَءَاكِلُونَ مِنْهَا فَمَالِـُٔونَ مِنْهَا ٱلْبُطُونَ","translationFa":"آنها [= مجرمان‌] از آن می‌خورند و شکمها را از آن پر می‌کنند!"},{"number":67,"arabic":"ثُمَّ إِنَّ لَهُمْ عَلَيْهَا لَشَوْبًۭا مِّنْ حَمِيمٍۢ","translationFa":"سپس روی آن آب داغ متعفّنی می‌نوشند!"},{"number":68,"arabic":"ثُمَّ إِنَّ مَرْجِعَهُمْ لَإِلَى ٱلْجَحِيمِ","translationFa":"سپس بازگشت آنها به سوی جهنّم است!"},{"number":69,"arabic":"إِنَّهُمْ أَلْفَوْا۟ ءَابَآءَهُمْ ضَآلِّينَ","translationFa":"چرا که آنها پدران خود را گمراه یافتند،"},{"number":70,"arabic":"فَهُمْ عَلَىٰٓ ءَاثَٰرِهِمْ يُهْرَعُونَ","translationFa":"با این حال به سرعت بدنبال آنان کشانده می‌شوند!"},{"number":71,"arabic":"وَلَقَدْ ضَلَّ قَبْلَهُمْ أَكْثَرُ ٱلْأَوَّلِينَ","translationFa":"و قبل از آنها بیشتر پیشینیان (نیز) گمراه شدند!"},{"number":72,"arabic":"وَلَقَدْ أَرْسَلْنَا فِيهِم مُّنذِرِينَ","translationFa":"ما در میان آنها انذارکنندگانی فرستادیم،"},{"number":73,"arabic":"فَٱنظُرْ كَيْفَ كَانَ عَٰقِبَةُ ٱلْمُنذَرِينَ","translationFa":"ولی بنگر عاقبت انذارشوندگان چگونه بود!"},{"number":74,"arabic":"إِلَّا عِبَادَ ٱللَّهِ ٱلْمُخْلَصِينَ","translationFa":"مگر بندگان مخلص خدا!"},{"number":75,"arabic":"وَلَقَدْ نَادَىٰنَا نُوحٌۭ فَلَنِعْمَ ٱلْمُجِيبُونَ","translationFa":"و نوح، ما را خواند (و ما دعای او را اجابت کردیم)؛ و چه خوب اجابت کننده‌ای هستیم!"},{"number":76,"arabic":"وَنَجَّيْنَٰهُ وَأَهْلَهُۥ مِنَ ٱلْكَرْبِ ٱلْعَظِيمِ","translationFa":"و او و خاندانش را از اندوه بزرگ رهایی بخشیدیم،"},{"number":77,"arabic":"وَجَعَلْنَا ذُرِّيَّتَهُۥ هُمُ ٱلْبَاقِينَ","translationFa":"و فرزندانش را همان بازماندگان (روی زمین) قرار دادیم،"},{"number":78,"arabic":"وَتَرَكْنَا عَلَيْهِ فِى ٱلْءَاخِرِينَ","translationFa":"و نام نیک او را در میان امّتهای بعد باقی نهادیم."},{"number":79,"arabic":"سَلَٰمٌ عَلَىٰ نُوحٍۢ فِى ٱلْعَٰلَمِينَ","translationFa":"سلام بر نوح در میان جهانیان باد!"},{"number":80,"arabic":"إِنَّا كَذَٰلِكَ نَجْزِى ٱلْمُحْسِنِينَ","translationFa":"ما این گونه نیکوکاران را پاداش می‌دهیم!"},{"number":81,"arabic":"إِنَّهُۥ مِنْ عِبَادِنَا ٱلْمُؤْمِنِينَ","translationFa":"چرا که او از بندگان باایمان ما بود!"},{"number":82,"arabic":"ثُمَّ أَغْرَقْنَا ٱلْءَاخَرِينَ","translationFa":"سپس دیگران [= دشمنان او] را غرق کردیم!"},{"number":83,"arabic":"۞ وَإِنَّ مِن شِيعَتِهِۦ لَإِبْرَٰهِيمَ","translationFa":"و از پیروان او ابراهیم بود؛"},{"number":84,"arabic":"إِذْ جَآءَ رَبَّهُۥ بِقَلْبٍۢ سَلِيمٍ","translationFa":"(به خاطر بیاور) هنگامی را که با قلب سلیم به پیشگاه پروردگارش آمد؛"},{"number":85,"arabic":"إِذْ قَالَ لِأَبِيهِ وَقَوْمِهِۦ مَاذَا تَعْبُدُونَ","translationFa":"هنگامی که به پدر و قومش گفت: «اینها چیست که می‌پرستید؟!"},{"number":86,"arabic":"أَئِفْكًا ءَالِهَةًۭ دُونَ ٱللَّهِ تُرِيدُونَ","translationFa":"آیا غیر از خدا به سراغ این معبودان دروغین می‌روید؟!"},{"number":87,"arabic":"فَمَا ظَنُّكُم بِرَبِّ ٱلْعَٰلَمِينَ","translationFa":"شما درباره پروردگار عالمیان چه گمان می‌برید؟!"},{"number":88,"arabic":"فَنَظَرَ نَظْرَةًۭ فِى ٱلنُّجُومِ","translationFa":"(سپس) نگاهی به ستارگان افکند..."},{"number":89,"arabic":"فَقَالَ إِنِّى سَقِيمٌۭ","translationFa":"و گفت: «من بیمارم (و با شما به مراسم جشن نمی‌آیم)!»"},{"number":90,"arabic":"فَتَوَلَّوْا۟ عَنْهُ مُدْبِرِينَ","translationFa":"آنها از او روی برتافته و به او پشت کردند (و بسرعت دور شدند.)"},{"number":91,"arabic":"فَرَاغَ إِلَىٰٓ ءَالِهَتِهِمْ فَقَالَ أَلَا تَأْكُلُونَ","translationFa":"(او وارد بتخانه شد) مخفیانه نگاهی به معبودانشان کرد و از روی تمسخر گفت: «چرا (از این غذاها) نمی‌خورید؟!"},{"number":92,"arabic":"مَا لَكُمْ لَا تَنطِقُونَ","translationFa":"(اصلاً) چرا سخن نمی‌گویید؟!»"},{"number":93,"arabic":"فَرَاغَ عَلَيْهِمْ ضَرْبًۢا بِٱلْيَمِينِ","translationFa":"سپس بسوی آنها رفت و ضربه‌ای محکم با دست راست بر پیکر آنها فرود آورد (و جز بت بزرگ، همه را درهم شکست)."},{"number":94,"arabic":"فَأَقْبَلُوٓا۟ إِلَيْهِ يَزِفُّونَ","translationFa":"آنها با سرعت به او روی آوردند."},{"number":95,"arabic":"قَالَ أَتَعْبُدُونَ مَا تَنْحِتُونَ","translationFa":"گفت: «آیا چیزی را می‌پرستید که با دست خود می‌تراشید؟!"},{"number":96,"arabic":"وَٱللَّهُ خَلَقَكُمْ وَمَا تَعْمَلُونَ","translationFa":"با اینکه خداوند هم شما را آفریده و هم بتهایی که می‌سازید!»"},{"number":97,"arabic":"قَالُوا۟ ٱبْنُوا۟ لَهُۥ بُنْيَٰنًۭا فَأَلْقُوهُ فِى ٱلْجَحِيمِ","translationFa":"(بت‌پرستان) گفتند: «بنای مرتفعی برای او بسازید و او را در جهنّمی از آتش بیفکنید!»"},{"number":98,"arabic":"فَأَرَادُوا۟ بِهِۦ كَيْدًۭا فَجَعَلْنَٰهُمُ ٱلْأَسْفَلِينَ","translationFa":"آنها طرحی برای نابودی ابراهیم ریخته بودند، ولی ما آنان را پست و مغلوب ساختیم!"},{"number":99,"arabic":"وَقَالَ إِنِّى ذَاهِبٌ إِلَىٰ رَبِّى سَيَهْدِينِ","translationFa":"(او از این مهلکه بسلامت بیرون آمد) و گفت: «من به سوی پروردگارم می‌روم، او مرا هدایت خواهد کرد!"},{"number":100,"arabic":"رَبِّ هَبْ لِى مِنَ ٱلصَّٰلِحِينَ","translationFa":"پروردگارا! به من از صالحان [= فرزندان صالح‌] ببخش!»"},{"number":101,"arabic":"فَبَشَّرْنَٰهُ بِغُلَٰمٍ حَلِيمٍۢ","translationFa":"ما او [= ابراهیم‌] را به نوجوانی بردبار و صبور بشارت دادیم!"},{"number":102,"arabic":"فَلَمَّا بَلَغَ مَعَهُ ٱلسَّعْىَ قَالَ يَٰبُنَىَّ إِنِّىٓ أَرَىٰ فِى ٱلْمَنَامِ أَنِّىٓ أَذْبَحُكَ فَٱنظُرْ مَاذَا تَرَىٰ ۚ قَالَ يَٰٓأَبَتِ ٱفْعَلْ مَا تُؤْمَرُ ۖ سَتَجِدُنِىٓ إِن شَآءَ ٱللَّهُ مِنَ ٱلصَّٰبِرِينَ","translationFa":"هنگامی که با او به مقام سعی و کوشش رسید، گفت: «پسرم! من در خواب دیدم که تو را ذبح می‌کنم، نظر تو چیست؟» گفت «پدرم! هر چه دستور داری اجرا کن، به خواست خدا مرا از صابران خواهی یافت!»"},{"number":103,"arabic":"فَلَمَّآ أَسْلَمَا وَتَلَّهُۥ لِلْجَبِينِ","translationFa":"هنگامی که هر دو تسلیم شدند و ابراهیم جبین او را بر خاک نهاد..."},{"number":104,"arabic":"وَنَٰدَيْنَٰهُ أَن يَٰٓإِبْرَٰهِيمُ","translationFa":"او را ندا دادیم که: «ای ابراهیم!"},{"number":105,"arabic":"قَدْ صَدَّقْتَ ٱلرُّءْيَآ ۚ إِنَّا كَذَٰلِكَ نَجْزِى ٱلْمُحْسِنِينَ","translationFa":"آن رؤیا را تحقق بخشیدی (و به مأموریت خود عمل کردی)!» ما این گونه، نیکوکاران را جزا می‌دهیم!"},{"number":106,"arabic":"إِنَّ هَٰذَا لَهُوَ ٱلْبَلَٰٓؤُا۟ ٱلْمُبِينُ","translationFa":"این مسلّماً همان امتحان آشکار است!"},{"number":107,"arabic":"وَفَدَيْنَٰهُ بِذِبْحٍ عَظِيمٍۢ","translationFa":"ما ذبح عظیمی را فدای او کردیم،"},{"number":108,"arabic":"وَتَرَكْنَا عَلَيْهِ فِى ٱلْءَاخِرِينَ","translationFa":"و نام نیک او را در امّتهای بعد باقی نهادیم!"},{"number":109,"arabic":"سَلَٰمٌ عَلَىٰٓ إِبْرَٰهِيمَ","translationFa":"سلام بر ابراهیم!"},{"number":110,"arabic":"كَذَٰلِكَ نَجْزِى ٱلْمُحْسِنِينَ","translationFa":"این گونه نیکوکاران را پاداش می‌دهیم!"},{"number":111,"arabic":"إِنَّهُۥ مِنْ عِبَادِنَا ٱلْمُؤْمِنِينَ","translationFa":"او از بندگان باایمان ما است!"},{"number":112,"arabic":"وَبَشَّرْنَٰهُ بِإِسْحَٰقَ نَبِيًّۭا مِّنَ ٱلصَّٰلِحِينَ","translationFa":"ما او را به اسحاق -پیامبری از شایستگان- بشارت دادیم!"},{"number":113,"arabic":"وَبَٰرَكْنَا عَلَيْهِ وَعَلَىٰٓ إِسْحَٰقَ ۚ وَمِن ذُرِّيَّتِهِمَا مُحْسِنٌۭ وَظَالِمٌۭ لِّنَفْسِهِۦ مُبِينٌۭ","translationFa":"ما به او و اسحاق برکت دادیم؛ و از دودمان آن دو، افرادی بودند نیکوکار و افرادی آشکارا به خود ستم کردند!"},{"number":114,"arabic":"وَلَقَدْ مَنَنَّا عَلَىٰ مُوسَىٰ وَهَٰرُونَ","translationFa":"ما به موسی و هارون نعمت بخشیدیم!"},{"number":115,"arabic":"وَنَجَّيْنَٰهُمَا وَقَوْمَهُمَا مِنَ ٱلْكَرْبِ ٱلْعَظِيمِ","translationFa":"و آن دو و قومشان را از اندوه بزرگ نجات دادیم!"},{"number":116,"arabic":"وَنَصَرْنَٰهُمْ فَكَانُوا۟ هُمُ ٱلْغَٰلِبِينَ","translationFa":"و آنها را یاری کردیم تا بر دشمنان خود پیروز شدند!"},{"number":117,"arabic":"وَءَاتَيْنَٰهُمَا ٱلْكِتَٰبَ ٱلْمُسْتَبِينَ","translationFa":"ما به آن دو، کتاب روشنگر دادیم،"},{"number":118,"arabic":"وَهَدَيْنَٰهُمَا ٱلصِّرَٰطَ ٱلْمُسْتَقِيمَ","translationFa":"و آن دو را به راه راست هدایت نمودیم!"},{"number":119,"arabic":"وَتَرَكْنَا عَلَيْهِمَا فِى ٱلْءَاخِرِينَ","translationFa":"و نام نیکشان را در اقوام بعد باقی گذاردیم!"},{"number":120,"arabic":"سَلَٰمٌ عَلَىٰ مُوسَىٰ وَهَٰرُونَ","translationFa":"سلام بر موسی و هارون!"},{"number":121,"arabic":"إِنَّا كَذَٰلِكَ نَجْزِى ٱلْمُحْسِنِينَ","translationFa":"ما این گونه نیکوکاران را پاداش می‌دهیم!"},{"number":122,"arabic":"إِنَّهُمَا مِنْ عِبَادِنَا ٱلْمُؤْمِنِينَ","translationFa":"آن دو از بندگان مؤمن ما بودند!"},{"number":123,"arabic":"وَإِنَّ إِلْيَاسَ لَمِنَ ٱلْمُرْسَلِينَ","translationFa":"و الیاس از رسولان (ما) بود!"},{"number":124,"arabic":"إِذْ قَالَ لِقَوْمِهِۦٓ أَلَا تَتَّقُونَ","translationFa":"به خاطر بیاور هنگامی را که به قومش گفت: «آیا تقوا پیشه نمی‌کنید؟!"},{"number":125,"arabic":"أَتَدْعُونَ بَعْلًۭا وَتَذَرُونَ أَحْسَنَ ٱلْخَٰلِقِينَ","translationFa":"آیا بت «بعل» را می‌خوانید و بهترین آفریدگارها را رها می‌سازید؟!"},{"number":126,"arabic":"ٱللَّهَ رَبَّكُمْ وَرَبَّ ءَابَآئِكُمُ ٱلْأَوَّلِينَ","translationFa":"خدایی که پروردگار شما و پروردگار نیاکان شماست!»"},{"number":127,"arabic":"فَكَذَّبُوهُ فَإِنَّهُمْ لَمُحْضَرُونَ","translationFa":"امّا آنها او را تکذیب کردند؛ ولی به یقین همگی (در دادگاه عدل الهی) احضار می‌شوند!"},{"number":128,"arabic":"إِلَّا عِبَادَ ٱللَّهِ ٱلْمُخْلَصِينَ","translationFa":"مگر بندگان مخلص خدا!"},{"number":129,"arabic":"وَتَرَكْنَا عَلَيْهِ فِى ٱلْءَاخِرِينَ","translationFa":"ما نام نیک او را در میان امّتهای بعد باقی گذاردیم!"},{"number":130,"arabic":"سَلَٰمٌ عَلَىٰٓ إِلْ يَاسِينَ","translationFa":"سلام بر الیاسین!"},{"number":131,"arabic":"إِنَّا كَذَٰلِكَ نَجْزِى ٱلْمُحْسِنِينَ","translationFa":"ما این گونه نیکوکاران را پاداش می‌دهیم!"},{"number":132,"arabic":"إِنَّهُۥ مِنْ عِبَادِنَا ٱلْمُؤْمِنِينَ","translationFa":"او از بندگان مؤمن ما است!"},{"number":133,"arabic":"وَإِنَّ لُوطًۭا لَّمِنَ ٱلْمُرْسَلِينَ","translationFa":"و لوط از رسولان (ما) است!"},{"number":134,"arabic":"إِذْ نَجَّيْنَٰهُ وَأَهْلَهُۥٓ أَجْمَعِينَ","translationFa":"و به خاطر بیاور زمانی را که او و خاندانش را همگی نجات دادیم،"},{"number":135,"arabic":"إِلَّا عَجُوزًۭا فِى ٱلْغَٰبِرِينَ","translationFa":"مگر پیرزنی که از بازماندگان بود (و به سرنوشت آنان گرفتار شد)!"},{"number":136,"arabic":"ثُمَّ دَمَّرْنَا ٱلْءَاخَرِينَ","translationFa":"سپس بقیه را نابود کردیم!"},{"number":137,"arabic":"وَإِنَّكُمْ لَتَمُرُّونَ عَلَيْهِم مُّصْبِحِينَ","translationFa":"و شما پیوسته صبحگاهان از کنار (ویرانه‌های شهرهای) آنها می‌گذرید..."},{"number":138,"arabic":"وَبِٱلَّيْلِ ۗ أَفَلَا تَعْقِلُونَ","translationFa":"و (همچنین) شبانگاه؛ آیا نمی‌اندیشید؟!"},{"number":139,"arabic":"وَإِنَّ يُونُسَ لَمِنَ ٱلْمُرْسَلِينَ","translationFa":"و یونس از رسولان (ما) است!"},{"number":140,"arabic":"إِذْ أَبَقَ إِلَى ٱلْفُلْكِ ٱلْمَشْحُونِ","translationFa":"به خاطر بیاور زمانی را که به سوی کشتی پر (از جمعیّت و بار) فرار کرد."},{"number":141,"arabic":"فَسَاهَمَ فَكَانَ مِنَ ٱلْمُدْحَضِينَ","translationFa":"و با آنها قرعه افکند، (و قرعه به نام او افتاد و) مغلوب شد!"},{"number":142,"arabic":"فَٱلْتَقَمَهُ ٱلْحُوتُ وَهُوَ مُلِيمٌۭ","translationFa":"(او را به دریا افکندند) و ماهی عظیمی او را بلعید، در حالی که مستحقّ سرزنش بود!"},{"number":143,"arabic":"فَلَوْلَآ أَنَّهُۥ كَانَ مِنَ ٱلْمُسَبِّحِينَ","translationFa":"و اگر او از تسبیح‌کنندگان نبود..."},{"number":144,"arabic":"لَلَبِثَ فِى بَطْنِهِۦٓ إِلَىٰ يَوْمِ يُبْعَثُونَ","translationFa":"تا روز قیامت در شکم ماهی می‌ماند!"},{"number":145,"arabic":"۞ فَنَبَذْنَٰهُ بِٱلْعَرَآءِ وَهُوَ سَقِيمٌۭ","translationFa":"(به هر حال ما او را رهایی بخشیدیم و) او را در یک سرزمین خشک خالی از گیاه افکندیم در حالی که بیمار بود!"},{"number":146,"arabic":"وَأَنۢبَتْنَا عَلَيْهِ شَجَرَةًۭ مِّن يَقْطِينٍۢ","translationFa":"و بوته کدوئی بر او رویاندیم (تا در سایه برگهای پهن و مرطوبش آرامش یابد)!"},{"number":147,"arabic":"وَأَرْسَلْنَٰهُ إِلَىٰ مِا۟ئَةِ أَلْفٍ أَوْ يَزِيدُونَ","translationFa":"و او را به سوی جمعیّت یکصد هزار نفری -یا بیشتر- فرستادیم!"},{"number":148,"arabic":"فَـَٔامَنُوا۟ فَمَتَّعْنَٰهُمْ إِلَىٰ حِينٍۢ","translationFa":"آنها ایمان آوردند، از این رو تا مدّت معلومی آنان را از مواهب زندگی بهره‌مند ساختیم!"},{"number":149,"arabic":"فَٱسْتَفْتِهِمْ أَلِرَبِّكَ ٱلْبَنَاتُ وَلَهُمُ ٱلْبَنُونَ","translationFa":"از آنان بپرس: آیا پروردگارت دخترانی دارد و پسران از آن آنهاست؟!"},{"number":150,"arabic":"أَمْ خَلَقْنَا ٱلْمَلَٰٓئِكَةَ إِنَٰثًۭا وَهُمْ شَٰهِدُونَ","translationFa":"آیا ما فرشتگان را مؤنث آفریدیم و آنها ناظر بودند؟!"},{"number":151,"arabic":"أَلَآ إِنَّهُم مِّنْ إِفْكِهِمْ لَيَقُولُونَ","translationFa":"بدانید آنها با این تهمت بزرگشان می‌گویند:"},{"number":152,"arabic":"وَلَدَ ٱللَّهُ وَإِنَّهُمْ لَكَٰذِبُونَ","translationFa":"«خداوند فرزند آورده!» ولی آنها به یقین دروغ می‌گویند!"},{"number":153,"arabic":"أَصْطَفَى ٱلْبَنَاتِ عَلَى ٱلْبَنِينَ","translationFa":"آیا دختران را بر پسران ترجیح داده است؟!"},{"number":154,"arabic":"مَا لَكُمْ كَيْفَ تَحْكُمُونَ","translationFa":"شما را چه شده است؟! چگونه حکم می‌کنید؟! (هیچ می‌فهمید چه می‌گویید؟!)"},{"number":155,"arabic":"أَفَلَا تَذَكَّرُونَ","translationFa":"آیا متذکّر نمی‌شوید؟!"},{"number":156,"arabic":"أَمْ لَكُمْ سُلْطَٰنٌۭ مُّبِينٌۭ","translationFa":"یا شما دلیل روشنی در این باره دارید؟"},{"number":157,"arabic":"فَأْتُوا۟ بِكِتَٰبِكُمْ إِن كُنتُمْ صَٰدِقِينَ","translationFa":"کتابتان را بیاورید اگر راست می‌گویید!"},{"number":158,"arabic":"وَجَعَلُوا۟ بَيْنَهُۥ وَبَيْنَ ٱلْجِنَّةِ نَسَبًۭا ۚ وَلَقَدْ عَلِمَتِ ٱلْجِنَّةُ إِنَّهُمْ لَمُحْضَرُونَ","translationFa":"آنها [= مشرکان‌] میان او [= خداوند] و جنّ، (خویشاوندی و) نسبتی قائل شدند؛ در حالی که جنّیان بخوبی می‌دانند که این بت‌پرستان در دادگاه الهی احضار می‌شوند!"},{"number":159,"arabic":"سُبْحَٰنَ ٱللَّهِ عَمَّا يَصِفُونَ","translationFa":"منزّه است خداوند از آنچه توصیف می‌کنند،"},{"number":160,"arabic":"إِلَّا عِبَادَ ٱللَّهِ ٱلْمُخْلَصِينَ","translationFa":"مگر بندگان مخلص خدا!"},{"number":161,"arabic":"فَإِنَّكُمْ وَمَا تَعْبُدُونَ","translationFa":"شما و آنچه را پرستش می‌کنید،"},{"number":162,"arabic":"مَآ أَنتُمْ عَلَيْهِ بِفَٰتِنِينَ","translationFa":"هرگز نمی‌توانید کسی را (با آن) فریب دهید،"},{"number":163,"arabic":"إِلَّا مَنْ هُوَ صَالِ ٱلْجَحِيمِ","translationFa":"مگر آنها که در آتش دوزخ وارد می‌شوند!"},{"number":164,"arabic":"وَمَا مِنَّآ إِلَّا لَهُۥ مَقَامٌۭ مَّعْلُومٌۭ","translationFa":"و هیچ یک از ما نیست جز آنکه مقام معلومی دارد؛"},{"number":165,"arabic":"وَإِنَّا لَنَحْنُ ٱلصَّآفُّونَ","translationFa":"و ما همگی (برای اطاعت فرمان خداوند) به صف ایستاده‌ایم؛"},{"number":166,"arabic":"وَإِنَّا لَنَحْنُ ٱلْمُسَبِّحُونَ","translationFa":"و ما همه تسبیح‌گوی او هستیم!"},{"number":167,"arabic":"وَإِن كَانُوا۟ لَيَقُولُونَ","translationFa":"آنها پیوسته می‌گفتند:"},{"number":168,"arabic":"لَوْ أَنَّ عِندَنَا ذِكْرًۭا مِّنَ ٱلْأَوَّلِينَ","translationFa":"«اگر یکی از کتابهای پیشینیان نزد ما بود،"},{"number":169,"arabic":"لَكُنَّا عِبَادَ ٱللَّهِ ٱلْمُخْلَصِينَ","translationFa":"به یقین، ما بندگان مخلص خدا بودیم!»"},{"number":170,"arabic":"فَكَفَرُوا۟ بِهِۦ ۖ فَسَوْفَ يَعْلَمُونَ","translationFa":"(امّا هنگامی که این کتاب بزرگ آسمانی بر آنها نازل شد،) به آن کافر شدند؛ ولی بزودی (نتیجه کار خود را) خواهند دانست!"},{"number":171,"arabic":"وَلَقَدْ سَبَقَتْ كَلِمَتُنَا لِعِبَادِنَا ٱلْمُرْسَلِينَ","translationFa":"وعده قطعی ما برای بندگان فرستاده ما از پیش مسلّم شده..."},{"number":172,"arabic":"إِنَّهُمْ لَهُمُ ٱلْمَنصُورُونَ","translationFa":"که آنان یاری شدگانند،"},{"number":173,"arabic":"وَإِنَّ جُندَنَا لَهُمُ ٱلْغَٰلِبُونَ","translationFa":"و لشکر ما پیروزند!"},{"number":174,"arabic":"فَتَوَلَّ عَنْهُمْ حَتَّىٰ حِينٍۢ","translationFa":"از آنها [= کافران‌] روی بگردان تا زمان معیّنی (که فرمان جهاد فرارسد)!"},{"number":175,"arabic":"وَأَبْصِرْهُمْ فَسَوْفَ يُبْصِرُونَ","translationFa":"و وضع آنها را بنگر (چه بی‌محتواست) اما بزودی (نتیجه اعمال خود را) می‌بینند!"},{"number":176,"arabic":"أَفَبِعَذَابِنَا يَسْتَعْجِلُونَ","translationFa":"آیا آنها برای عذاب ما شتاب می‌کنند؟!"},{"number":177,"arabic":"فَإِذَا نَزَلَ بِسَاحَتِهِمْ فَسَآءَ صَبَاحُ ٱلْمُنذَرِينَ","translationFa":"امّا هنگامی که عذاب ما در آستانه خانه‌هایشان فرود آید، انذارشدگان صبحگاه بدی خواهند داشت!"},{"number":178,"arabic":"وَتَوَلَّ عَنْهُمْ حَتَّىٰ حِينٍۢ","translationFa":"از آنان روی بگردان تا زمان معیّنی!"},{"number":179,"arabic":"وَأَبْصِرْ فَسَوْفَ يُبْصِرُونَ","translationFa":"و وضع کارشان را ببین؛ آنها نیز به زودی (نتیجه اعمال خود را) می‌بینند!"},{"number":180,"arabic":"سُبْحَٰنَ رَبِّكَ رَبِّ ٱلْعِزَّةِ عَمَّا يَصِفُونَ","translationFa":"منزّه است پروردگار تو، پروردگار عزّت (و قدرت) از آنچه آنان توصیف می‌کنند."},{"number":181,"arabic":"وَسَلَٰمٌ عَلَى ٱلْمُرْسَلِينَ","translationFa":"و سلام بر رسولان!"},{"number":182,"arabic":"وَٱلْحَمْدُ لِلَّهِ رَبِّ ٱلْعَٰلَمِينَ","translationFa":"حمد و ستایش مخصوص خداوندی است که پروردگار جهانیان است!"}],"51":[{"number":1,"arabic":"بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ وَٱلذَّٰرِيَٰتِ ذَرْوًۭا","translationFa":"سوگند به بادهایی که (ابرها را) به حرکت درمی‌آورند،"},{"number":2,"arabic":"فَٱلْحَٰمِلَٰتِ وِقْرًۭا","translationFa":"سوگند به آن ابرها که بار سنگینی (از باران را) با خود حمل می‌کنند،"},{"number":3,"arabic":"فَٱلْجَٰرِيَٰتِ يُسْرًۭا","translationFa":"و سوگند به کشتیهایی که به آسانی به حرکت درمی‌آیند،"},{"number":4,"arabic":"فَٱلْمُقَسِّمَٰتِ أَمْرًا","translationFa":"و سوگند به فرشتگانی که کارها را تقسیم می‌کنند،"},{"number":5,"arabic":"إِنَّمَا تُوعَدُونَ لَصَادِقٌۭ","translationFa":"(آری سوگند به همه اینها) که آنچه به شما وعده شده قطعاً راست است؛"},{"number":6,"arabic":"وَإِنَّ ٱلدِّينَ لَوَٰقِعٌۭ","translationFa":"و بی‌شکّ (رستاخیز) و جزای اعمال واقع‌شدنی است!"},{"number":7,"arabic":"وَٱلسَّمَآءِ ذَاتِ ٱلْحُبُكِ","translationFa":"قسم به آسمان که دارای چین و شکنهای زیباست،"},{"number":8,"arabic":"إِنَّكُمْ لَفِى قَوْلٍۢ مُّخْتَلِفٍۢ","translationFa":"که شما (درباره قیامت) در گفتاری مختلف و گوناگونید!"},{"number":9,"arabic":"يُؤْفَكُ عَنْهُ مَنْ أُفِكَ","translationFa":"(تنها) کسی از ایمان به آن منحرف می‌شود که از قبول حقّ سرباز می‌زند!"},{"number":10,"arabic":"قُتِلَ ٱلْخَرَّٰصُونَ","translationFa":"کشته باد دروغگویان (و مرگ بر آنها)!"},{"number":11,"arabic":"ٱلَّذِينَ هُمْ فِى غَمْرَةٍۢ سَاهُونَ","translationFa":"همانها که در جهل و غفلت فرو رفته‌اند،"},{"number":12,"arabic":"يَسْـَٔلُونَ أَيَّانَ يَوْمُ ٱلدِّينِ","translationFa":"و پیوسته سؤال می‌کنند: «روز جزا چه موقع است؟!»"},{"number":13,"arabic":"يَوْمَ هُمْ عَلَى ٱلنَّارِ يُفْتَنُونَ","translationFa":"(آری) همان روزی است که آنها را بر آتش می‌سوزانند!"},{"number":14,"arabic":"ذُوقُوا۟ فِتْنَتَكُمْ هَٰذَا ٱلَّذِى كُنتُم بِهِۦ تَسْتَعْجِلُونَ","translationFa":"(و گفته می‌شود:) بچشید عذاب خود را، این همان چیزی است که برای آن شتاب داشتید!"},{"number":15,"arabic":"إِنَّ ٱلْمُتَّقِينَ فِى جَنَّٰتٍۢ وَعُيُونٍ","translationFa":"به یقین، پرهیزگاران در باغهای بهشت و در میان چشمه‌ها قرار دارند،"},{"number":16,"arabic":"ءَاخِذِينَ مَآ ءَاتَىٰهُمْ رَبُّهُمْ ۚ إِنَّهُمْ كَانُوا۟ قَبْلَ ذَٰلِكَ مُحْسِنِينَ","translationFa":"و آنچه پروردگارشان به آنها بخشیده دریافت می‌دارند، زیرا پیش از آن (در سرای دنیا) از نیکوکاران بودند!"},{"number":17,"arabic":"كَانُوا۟ قَلِيلًۭا مِّنَ ٱلَّيْلِ مَا يَهْجَعُونَ","translationFa":"آنها کمی از شب را می‌خوابیدند،"},{"number":18,"arabic":"وَبِٱلْأَسْحَارِ هُمْ يَسْتَغْفِرُونَ","translationFa":"و در سحرگاهان استغفار می‌کردند،"},{"number":19,"arabic":"وَفِىٓ أَمْوَٰلِهِمْ حَقٌّۭ لِّلسَّآئِلِ وَٱلْمَحْرُومِ","translationFa":"و در اموال آنها حقّی برای سائل و محروم بود!"},{"number":20,"arabic":"وَفِى ٱلْأَرْضِ ءَايَٰتٌۭ لِّلْمُوقِنِينَ","translationFa":"و در زمین آیاتی برای جویندگان یقین است،"},{"number":21,"arabic":"وَفِىٓ أَنفُسِكُمْ ۚ أَفَلَا تُبْصِرُونَ","translationFa":"و در وجود خود شما (نیز آیاتی است)؛ آیا نمی‌بینید؟!"},{"number":22,"arabic":"وَفِى ٱلسَّمَآءِ رِزْقُكُمْ وَمَا تُوعَدُونَ","translationFa":"و روزی شما در آسمان است و آنچه به شما وعده داده می‌شود!"},{"number":23,"arabic":"فَوَرَبِّ ٱلسَّمَآءِ وَٱلْأَرْضِ إِنَّهُۥ لَحَقٌّۭ مِّثْلَ مَآ أَنَّكُمْ تَنطِقُونَ","translationFa":"سوگند به پروردگار آسمان و زمین که این مطلب حقّ است همان گونه که شما سخن می‌گویید!"},{"number":24,"arabic":"هَلْ أَتَىٰكَ حَدِيثُ ضَيْفِ إِبْرَٰهِيمَ ٱلْمُكْرَمِينَ","translationFa":"آیا خبر مهمانهای بزرگوار ابراهیم به تو رسیده است؟"},{"number":25,"arabic":"إِذْ دَخَلُوا۟ عَلَيْهِ فَقَالُوا۟ سَلَٰمًۭا ۖ قَالَ سَلَٰمٌۭ قَوْمٌۭ مُّنكَرُونَ","translationFa":"در آن زمان که بر او وارد شدند و گفتند: «سلام بر تو!» او گفت: «سلام بر شما که جمعیّتی ناشناخته‌اید!»"},{"number":26,"arabic":"فَرَاغَ إِلَىٰٓ أَهْلِهِۦ فَجَآءَ بِعِجْلٍۢ سَمِينٍۢ","translationFa":"سپس پنهانی به سوی خانواده خود رفت و گوساله فربه (و بریان شده‌ای را برای آنها) آورد،"},{"number":27,"arabic":"فَقَرَّبَهُۥٓ إِلَيْهِمْ قَالَ أَلَا تَأْكُلُونَ","translationFa":"و نزدیک آنها گذارد، (ولی با تعجّب دید دست بسوی غذا نمی‌برند) گفت: «آیا شما غذا نمی‌خورید؟!»"},{"number":28,"arabic":"فَأَوْجَسَ مِنْهُمْ خِيفَةًۭ ۖ قَالُوا۟ لَا تَخَفْ ۖ وَبَشَّرُوهُ بِغُلَٰمٍ عَلِيمٍۢ","translationFa":"و از آنها احساس وحشت کرد، گفتند: «نترس (ما رسولان و فرشتگان پروردگار توایم)!» و او را بشارت به تولّد پسری دانا دادند."},{"number":29,"arabic":"فَأَقْبَلَتِ ٱمْرَأَتُهُۥ فِى صَرَّةٍۢ فَصَكَّتْ وَجْهَهَا وَقَالَتْ عَجُوزٌ عَقِيمٌۭ","translationFa":"در این هنگام همسرش جلو آمد در حالی که (از خوشحالی و تعجّب) فریاد می‌کشید به صورت خود زد و گفت: «(آیا پسری خواهم آورد در حالی که) پیرزنی نازا هستم؟!»"},{"number":30,"arabic":"قَالُوا۟ كَذَٰلِكِ قَالَ رَبُّكِ ۖ إِنَّهُۥ هُوَ ٱلْحَكِيمُ ٱلْعَلِيمُ","translationFa":"گفتند: «پروردگارت چنین گفته است، و او حکیم و داناست!»"},{"number":31,"arabic":"۞ قَالَ فَمَا خَطْبُكُمْ أَيُّهَا ٱلْمُرْسَلُونَ","translationFa":"(ابراهیم) گفت: «مأموریت شما چیست ای فرستادگان (خدا)؟»"},{"number":32,"arabic":"قَالُوٓا۟ إِنَّآ أُرْسِلْنَآ إِلَىٰ قَوْمٍۢ مُّجْرِمِينَ","translationFa":"گفتند: «ما به سوی قوم مجرمی فرستاده شده‌ایم..."},{"number":33,"arabic":"لِنُرْسِلَ عَلَيْهِمْ حِجَارَةًۭ مِّن طِينٍۢ","translationFa":"تا بارانی از «سنگ - گِل» بر آنها بفرستیم؛"},{"number":34,"arabic":"مُّسَوَّمَةً عِندَ رَبِّكَ لِلْمُسْرِفِينَ","translationFa":"سنگهایی که از ناحیه پروردگارت برای اسرافکاران نشان گذاشته شده است!»"},{"number":35,"arabic":"فَأَخْرَجْنَا مَن كَانَ فِيهَا مِنَ ٱلْمُؤْمِنِينَ","translationFa":"ما مؤمنانی را که در آن شهرها (ی قوم لوط) زندگی می‌کردند (قبل از نزول عذاب) خارج کردیم،"},{"number":36,"arabic":"فَمَا وَجَدْنَا فِيهَا غَيْرَ بَيْتٍۢ مِّنَ ٱلْمُسْلِمِينَ","translationFa":"ولی جز یک خانواده باایمان در تمام آنها نیافتیم!"},{"number":37,"arabic":"وَتَرَكْنَا فِيهَآ ءَايَةًۭ لِّلَّذِينَ يَخَافُونَ ٱلْعَذَابَ ٱلْأَلِيمَ","translationFa":"و در آن (شهرهای بلا دیده) نشانه‌ای روشن برای کسانی که از عذاب دردناک می‌ترسند به جای گذاردیم."},{"number":38,"arabic":"وَفِى مُوسَىٰٓ إِذْ أَرْسَلْنَٰهُ إِلَىٰ فِرْعَوْنَ بِسُلْطَٰنٍۢ مُّبِينٍۢ","translationFa":"و در (زندگی) موسی نیز (نشانه و درس عبرتی بود) هنگامی که او را با دلیلی آشکار به سوی فرعون فرستادیم؛"},{"number":39,"arabic":"فَتَوَلَّىٰ بِرُكْنِهِۦ وَقَالَ سَٰحِرٌ أَوْ مَجْنُونٌۭ","translationFa":"امّا او با تمام وجودش از وی روی برتافت و گفت: «این مرد یا ساحر است یا دیوانه!»"},{"number":40,"arabic":"فَأَخَذْنَٰهُ وَجُنُودَهُۥ فَنَبَذْنَٰهُمْ فِى ٱلْيَمِّ وَهُوَ مُلِيمٌۭ","translationFa":"از این رو ما او و لشکریانش را گرفتیم و به دریا افکندیم در حالی که در خور سرزنش بود!"},{"number":41,"arabic":"وَفِى عَادٍ إِذْ أَرْسَلْنَا عَلَيْهِمُ ٱلرِّيحَ ٱلْعَقِيمَ","translationFa":"و (همچنین) در سرگذشت «عاد» (آیتی است) در آن هنگام که تندبادی بی‌باران بر آنها فرستادیم،"},{"number":42,"arabic":"مَا تَذَرُ مِن شَىْءٍ أَتَتْ عَلَيْهِ إِلَّا جَعَلَتْهُ كَٱلرَّمِيمِ","translationFa":"که بر هیچ چیز نمی‌گذشت مگر اینکه آن را همچون استخوانهای پوسیده می‌ساخت."},{"number":43,"arabic":"وَفِى ثَمُودَ إِذْ قِيلَ لَهُمْ تَمَتَّعُوا۟ حَتَّىٰ حِينٍۢ","translationFa":"و نیز در سرگذشت قوم «ثمود» عبرتی است در آن هنگام که به آنان گفته شد: «مدّتی کوتاه بهره‌مند باشید (و سپس منتظر عذاب)!»"},{"number":44,"arabic":"فَعَتَوْا۟ عَنْ أَمْرِ رَبِّهِمْ فَأَخَذَتْهُمُ ٱلصَّٰعِقَةُ وَهُمْ يَنظُرُونَ","translationFa":"آنها از فرمان پروردگارشان سرباز زدند، و صاعقه آنان را فراگرفت در حالی که (خیره خیره) نگاه می‌کردند (بی‌آنکه قدرت دفاع داشته باشند)!"},{"number":45,"arabic":"فَمَا ٱسْتَطَٰعُوا۟ مِن قِيَامٍۢ وَمَا كَانُوا۟ مُنتَصِرِينَ","translationFa":"چنان بر زمین افتادند که توان برخاستن نداشتند و نتوانستند از کسی یاری طلبند!"},{"number":46,"arabic":"وَقَوْمَ نُوحٍۢ مِّن قَبْلُ ۖ إِنَّهُمْ كَانُوا۟ قَوْمًۭا فَٰسِقِينَ","translationFa":"همچنین قوم نوح را پیش از آنها هلاک کردیم، چرا که قوم فاسقی بودند!"},{"number":47,"arabic":"وَٱلسَّمَآءَ بَنَيْنَٰهَا بِأَيْي۟دٍۢ وَإِنَّا لَمُوسِعُونَ","translationFa":"و ما آسمان را با قدرت بنا کردیم، و همواره آن را وسعت می‌بخشیم!"},{"number":48,"arabic":"وَٱلْأَرْضَ فَرَشْنَٰهَا فَنِعْمَ ٱلْمَٰهِدُونَ","translationFa":"و زمین را گستردیم، و چه خوب گستراننده‌ای هستیم!"},{"number":49,"arabic":"وَمِن كُلِّ شَىْءٍ خَلَقْنَا زَوْجَيْنِ لَعَلَّكُمْ تَذَكَّرُونَ","translationFa":"و از هر چیز دو جفت آفریدیم، شاید متذکّر ��وید!"},{"number":50,"arabic":"فَفِرُّوٓا۟ إِلَى ٱللَّهِ ۖ إِنِّى لَكُم مِّنْهُ نَذِيرٌۭ مُّبِينٌۭ","translationFa":"پس به سوی خدا بگریزید، که من از سوی او برای شما بیم‌دهنده‌ای آشکارم!"},{"number":51,"arabic":"وَلَا تَجْعَلُوا۟ مَعَ ٱللَّهِ إِلَٰهًا ءَاخَرَ ۖ إِنِّى لَكُم مِّنْهُ نَذِيرٌۭ مُّبِينٌۭ","translationFa":"و با خدا معبود دیگری قرار ندهید، که من برای شما از سوی او بیم‌دهنده‌ای آشکارم!"},{"number":52,"arabic":"كَذَٰلِكَ مَآ أَتَى ٱلَّذِينَ مِن قَبْلِهِم مِّن رَّسُولٍ إِلَّا قَالُوا۟ سَاحِرٌ أَوْ مَجْنُونٌ","translationFa":"این گونه است که هیچ پیامبری قبل از اینها بسوی قومی فرستاده نشد مگر اینکه گفتند: «او ساحر است یا دیوانه!»"},{"number":53,"arabic":"أَتَوَاصَوْا۟ بِهِۦ ۚ بَلْ هُمْ قَوْمٌۭ طَاغُونَ","translationFa":"آیا یکدیگر را به آن سفارش می‌کردند (که همه چنین تهمتی بزنند)؟! نه، بلکه آنها قومی طغیانگرند."},{"number":54,"arabic":"فَتَوَلَّ عَنْهُمْ فَمَآ أَنتَ بِمَلُومٍۢ","translationFa":"حال که چنین است از آنها روی بگردان که هرگز در خور ملامت نخواهی بود؛"},{"number":55,"arabic":"وَذَكِّرْ فَإِنَّ ٱلذِّكْرَىٰ تَنفَعُ ٱلْمُؤْمِنِينَ","translationFa":"و پیوسته تذکّر ده، زیرا تذکّر مؤمنان را سود می‌بخشد."},{"number":56,"arabic":"وَمَا خَلَقْتُ ٱلْجِنَّ وَٱلْإِنسَ إِلَّا لِيَعْبُدُونِ","translationFa":"من جنّ و انس را نیافریدم جز برای اینکه عبادتم کنند (و از این راه تکامل یابند و به من نزدیک شوند)!"},{"number":57,"arabic":"مَآ أُرِيدُ مِنْهُم مِّن رِّزْقٍۢ وَمَآ أُرِيدُ أَن يُطْعِمُونِ","translationFa":"هرگز از آنها روزی نمی‌خواهم، و نمی‌خواهم مرا اطعام کنند!"},{"number":58,"arabic":"إِنَّ ٱللَّهَ هُوَ ٱلرَّزَّاقُ ذُو ٱلْقُوَّةِ ٱلْمَتِينُ","translationFa":"خداوند روزی‌دهنده و صاحب قوّت و قدرت است!"},{"number":59,"arabic":"فَإِنَّ لِلَّذِينَ ظَلَمُوا۟ ذَنُوبًۭا مِّثْلَ ذَنُوبِ أَصْحَٰبِهِمْ فَلَا يَسْتَعْجِلُونِ","translationFa":"و برای کسانی که ستم کردند، سهم بزرگی از عذاب است همانند سهم یارانشان (از اقوام ستمگر پیشین)؛ بنابر این عجله نکنند!"},{"number":60,"arabic":"فَوَيْلٌۭ لِّلَّذِينَ كَفَرُوا۟ مِن يَوْمِهِمُ ٱلَّذِى يُوعَدُونَ","translationFa":"پس وای بر کسانی که کافر شدند از روزی که به آنها وعده داده می‌شود!"}],"55":[{"number":1,"arabic":"بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ ٱلرَّحْمَٰنُ","translationFa":"خداوند رحمان،"},{"number":2,"arabic":"عَلَّمَ ٱلْقُرْءَانَ","translationFa":"قرآن را تعلیم فرمود،"},{"number":3,"arabic":"خَلَقَ ٱلْإِنسَٰنَ","translationFa":"انسان را آفرید،"},{"number":4,"arabic":"عَلَّمَهُ ٱلْبَيَانَ","translationFa":"و به او «بیان» را آموخت."},{"number":5,"arabic":"ٱلشَّمْسُ وَٱلْقَمَرُ بِحُسْبَانٍۢ","translationFa":"خورشید و ماه با حساب منظّمی می‌گردند،"},{"number":6,"arabic":"وَٱلنَّجْمُ وَٱلشَّجَرُ يَسْجُدَانِ","translationFa":"و گیاه و درخت برای او سجده می‌کنند!"},{"number":7,"arabic":"وَٱلسَّمَآءَ رَفَعَهَا وَوَضَعَ ٱلْمِيزَانَ","translationFa":"و آسمان را برافراشت، و میزان و قانون (در آن) گذاشت،"},{"number":8,"arabic":"أَلَّا تَطْغَوْا۟ فِى ٱلْمِيزَانِ","translationFa":"تا در میزان طغیان نکنید (و از مسیر عدالت منحرف نشوید)،"},{"number":9,"arabic":"وَأَقِيمُوا۟ ٱلْوَزْنَ بِٱلْقِسْطِ وَلَا تُخْسِرُوا۟ ٱلْمِيزَانَ","translationFa":"و وزن را بر اساس عدل برپا دارید و میزان را کم نگذارید!"},{"number":10,"arabic":"وَٱلْأَرْضَ وَضَعَهَا لِلْأَنَامِ","translationFa":"زمین را برای خلایق آفرید،"},{"number":11,"arabic":"فِيهَا فَٰكِهَةٌۭ وَٱلنَّخْلُ ذَاتُ ٱلْأَكْمَامِ","translationFa":"که در آن میوه‌ها و نخلهای پرشکوفه است،"},{"number":12,"arabic":"وَٱلْحَبُّ ذُو ٱلْعَصْفِ وَٱلرَّيْحَانُ","translationFa":"و دانه‌هایی که همراه با ساقه و برگی است که بصورت کاه درمی‌آید، و گیاهان خوشبو!"},{"number":13,"arabic":"فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ","translationFa":"پس کدامین نعمتهای پروردگارتان را تکذیب می‌کنید (شما ای گروه جنّ و انس)؟!"},{"number":14,"arabic":"خَلَقَ ٱلْإِنسَٰنَ مِن صَلْصَٰلٍۢ كَٱلْفَخَّارِ","translationFa":"انسان را از گِل خشکیده‌ای همچون سفال آفرید،"},{"number":15,"arabic":"وَخَلَقَ ٱلْجَآنَّ مِن مَّارِجٍۢ مِّن نَّارٍۢ","translationFa":"و جنّ را از شعله‌های مختلط و متحرّک آتش خلق کرد!"},{"number":16,"arabic":"فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ","translationFa":"پس کدامین نعمتهای پروردگارتان را انکار می‌کنید؟!"},{"number":17,"arabic":"رَبُّ ٱلْمَشْرِقَيْنِ وَرَبُّ ٱلْمَغْرِبَيْنِ","translationFa":"او پروردگار دو مشرق و پروردگار دو مغرب است!"},{"number":18,"arabic":"فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ","translationFa":"پس کدامین نعمتهای پروردگارتان را انکار می‌کنید؟!"},{"number":19,"arabic":"مَرَجَ ٱلْبَحْرَيْنِ يَلْتَقِيَانِ","translationFa":"دو دریای مختلف (شور و شیرین، گرم و سرد) را در کنار هم قرار داد، در حالی که با هم تماس دارند؛"},{"number":20,"arabic":"بَيْنَهُمَا بَرْزَخٌۭ لَّا يَبْغِيَانِ","translationFa":"در میان آن دو برزخی است که یکی بر دیگری غلبه نمی‌کند (و به هم نمی‌آمیزند)!"},{"number":21,"arabic":"فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ","translationFa":"پس کدامین نعمتهای پروردگارتان را انکار می‌کنید؟!"},{"number":22,"arabic":"يَخْرُجُ مِنْهُمَا ٱللُّؤْلُؤُ وَٱلْمَرْجَانُ","translationFa":"از آن دو، لؤلؤ و مرجان خارج می‌شود."},{"number":23,"arabic":"فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ","translationFa":"پس کدامین نعمتهای پروردگارتان را انکار می‌کنید؟!"},{"number":24,"arabic":"وَلَهُ ٱلْجَوَارِ ٱلْمُنشَـَٔاتُ فِى ٱلْبَحْرِ كَٱلْأَعْلَٰمِ","translationFa":"و برای اوست کشتیهای ساخته شده که در دریا به حرکت درمی‌آیند و همچون کوهی هستند!"},{"number":25,"arabic":"فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ","translationFa":"پس کدامین نعمتهای پروردگارتان را انکار می‌کنید؟!"},{"number":26,"arabic":"كُلُّ مَنْ عَلَيْهَا فَانٍۢ","translationFa":"همه کسانی که روی آن [= زمین‌] هستند فانی می‌شوند،"},{"number":27,"arabic":"وَيَبْقَىٰ وَجْهُ رَبِّكَ ذُو ٱلْجَلَٰلِ وَٱلْإِكْرَامِ","translationFa":"و تنها ذات ذوالجلال و گرامی پروردگارت باقی می‌ماند!"},{"number":28,"arabic":"فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ","translationFa":"پس کدامین نعمتهای پروردگارتان را انکار می‌کنید؟!"},{"number":29,"arabic":"يَسْـَٔلُهُۥ مَن فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ ۚ كُلَّ يَوْمٍ هُوَ فِى شَأْنٍۢ","translationFa":"تمام کسانی که در آسمانها و زمین هستند از او تقاضا می‌کنند، و او هر روز در شأن و کاری است!"},{"number":30,"arabic":"فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ","translationFa":"پس کدامین نعمتهای پروردگارتان را انکار می‌کنید؟!"},{"number":31,"arabic":"سَنَفْرُغُ لَكُمْ أَيُّهَ ٱلثَّقَلَانِ","translationFa":"بزودی به حساب شما می‌پردازیم ای دو گروه انس و جنّ!"},{"number":32,"arabic":"فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ","translationFa":"پس کدامین نعمتهای پروردگارتان را انکار می‌کنید؟!"},{"number":33,"arabic":"يَٰمَعْشَرَ ٱلْجِنِّ وَٱلْإِنسِ إِنِ ٱسْتَطَعْتُمْ أَن تَنفُذُوا۟ مِنْ أَقْطَارِ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ فَٱنفُذُوا۟ ۚ لَا تَنفُذُونَ إِلَّا بِسُلْطَٰنٍۢ","translationFa":"ای گروه جنّ و انس! اگر می‌توانید از مرزهای آسمانها و زمین بگذرید، پس بگذرید، ولی هرگز نمی‌توانید، مگر با نیرویی (فوق العاده)!"},{"number":34,"arabic":"فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ","translationFa":"پس کدامین نعمتهای پروردگارتان را انکار می‌کنید؟!"},{"number":35,"arabic":"يُرْسَلُ عَلَيْكُمَا شُوَاظٌۭ مِّن نَّارٍۢ وَنُحَاسٌۭ فَلَا تَنتَصِرَانِ","translationFa":"شعله‌هایی از آتش بی‌دود، و دودهایی متراکم بر شما فرستاده می‌شود؛ و نمی‌توانید از کسی یاری بطلبید!"},{"number":36,"arabic":"فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ","translationFa":"پس کدامین نعمتهای پروردگارتان را انکار می‌کنید؟!"},{"number":37,"arabic":"فَإِذَا ٱنشَقَّتِ ٱلسَّمَآءُ فَكَانَتْ وَرْدَةًۭ كَٱلدِّهَانِ","translationFa":"در آن هنگام که آسمان شکافته شود و همچون روغن مذاب گلگون گردد (حوادث هولناکی رخ می‌دهد که تاب تحمل آن را نخواهید داشت)!"},{"number":38,"arabic":"فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ","translationFa":"پس کدامین نعمتهای پروردگارتان را انکار می‌کنید؟!"},{"number":39,"arabic":"فَيَوْمَئِذٍۢ لَّا يُسْـَٔلُ عَن ذَنۢبِهِۦٓ إِنسٌۭ وَلَا جَآنٌّۭ","translationFa":"در آن روز هیچ کس از انس و جنّ از گناهش سؤال نمی‌شود (و همه چیز روشن است)!"},{"number":40,"arabic":"فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ","translationFa":"پس کدامین نعمتهای پروردگارتان را انکار می‌کنید؟!"},{"number":41,"arabic":"يُعْرَفُ ٱلْمُجْرِمُونَ بِسِيمَٰهُمْ فَيُؤْخَذُ بِٱلنَّوَٰصِى وَٱلْأَقْدَامِ","translationFa":"مجرمان از چهره‌هایشان شناخته می‌شوند؛ و آنگاه آنها را از موهای پیش سر، و پاهایشان می‌گیرند (و به دوزخ می‌افکنند)!"},{"number":42,"arabic":"فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ","translationFa":"پس کدامین نعمتهای پروردگارتان را انکار می‌کنید؟!"},{"number":43,"arabic":"هَٰذِهِۦ جَهَنَّمُ ٱلَّتِى يُكَذِّبُ بِهَا ٱلْمُجْرِمُونَ","translationFa":"این همان دوزخی است که مجرمان آن را انکار می‌کردند!"},{"number":44,"arabic":"يَطُوفُونَ بَيْنَهَا وَبَيْنَ حَمِيمٍ ءَانٍۢ","translationFa":"امروز در میان آن و آب سوزان در رفت و آمدند!"},{"number":45,"arabic":"فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ","translationFa":"پس کدامین نعمتهای پروردگارتان را انکار می‌کنید؟!"},{"number":46,"arabic":"وَلِمَنْ خَافَ مَقَامَ رَبِّهِۦ جَنَّتَانِ","translationFa":"و برای کسی که از مقام پروردگارش بترسد، دو باغ بهشتی است!"},{"number":47,"arabic":"فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ","translationFa":"پس کدامین نعمتهای پروردگارتان را انکار می‌کنید؟!"},{"number":48,"arabic":"ذَوَاتَآ أَفْنَانٍۢ","translationFa":"(آن دو باغ بهشتی) دارای انواع نعمتها و درختان پرطراوت است!"},{"number":49,"arabic":"فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ","translationFa":"پس کدامین نعمتهای پروردگارتان را انکار می‌کنید؟!"},{"number":50,"arabic":"فِيهِمَا عَيْنَانِ تَجْرِيَانِ","translationFa":"در آنها دو چشمه همیشه جاری است!"},{"number":51,"arabic":"فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ","translationFa":"پس کدامین نعمتهای پروردگارتان را انکار می‌کنید؟!"},{"number":52,"arabic":"فِيهِمَا مِن كُلِّ فَٰكِهَةٍۢ زَوْجَانِ","translationFa":"در آن دو، از هر میوه‌ای دو نوع وجود دارد (هر یک از دیگری بهتر)!"},{"number":53,"arabic":"فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ","translationFa":"پس کدامین نعمتهای پروردگارتان را انکار می‌کنید؟!"},{"number":54,"arabic":"مُتَّكِـِٔينَ عَلَىٰ فُرُشٍۭ بَطَآئِنُهَا مِنْ إِسْتَبْرَقٍۢ ۚ وَجَنَى ٱلْجَنَّتَيْنِ دَانٍۢ","translationFa":"این در حالی است ��ه آنها بر فرشهایی تکیه کرده‌اند با آسترهائی از دیبا و ابریشم، و میوه‌های رسیده آن دو باغ بهشتی در دسترس است!"},{"number":55,"arabic":"فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ","translationFa":"پس کدامین نعمتهای پروردگارتان را انکار می‌کنید؟!"},{"number":56,"arabic":"فِيهِنَّ قَٰصِرَٰتُ ٱلطَّرْفِ لَمْ يَطْمِثْهُنَّ إِنسٌۭ قَبْلَهُمْ وَلَا جَآنٌّۭ","translationFa":"در آن باغهای بهشتی زنانی هستند که جز به همسران خود عشق نمی‌ورزند؛ و هیچ انس و جنّ پیش از اینها با آنان تماس نگرفته است."},{"number":57,"arabic":"فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ","translationFa":"پس کدامین نعمتهای پروردگارتان را انکار می‌کنید؟!"},{"number":58,"arabic":"كَأَنَّهُنَّ ٱلْيَاقُوتُ وَٱلْمَرْجَانُ","translationFa":"آنها همچون یاقوت و مرجانند!"},{"number":59,"arabic":"فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ","translationFa":"پس کدامین نعمتهای پروردگارتان را انکار می‌کنید؟!"},{"number":60,"arabic":"هَلْ جَزَآءُ ٱلْإِحْسَٰنِ إِلَّا ٱلْإِحْسَٰنُ","translationFa":"آیا جزای نیکی جز نیکی است؟!"},{"number":61,"arabic":"فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ","translationFa":"پس کدامین نعمتهای پروردگارتان را انکار می‌کنید؟!"},{"number":62,"arabic":"وَمِن دُونِهِمَا جَنَّتَانِ","translationFa":"و پایین تر از آنها، دو باغ بهشتی دیگر است."},{"number":63,"arabic":"فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ","translationFa":"پس کدامین نعمتهای پروردگارتان را انکار می‌کنید؟!"},{"number":64,"arabic":"مُدْهَآمَّتَانِ","translationFa":"هر دو خرّم و سرسبزند!"},{"number":65,"arabic":"فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ","translationFa":"پس کدامین نعمتهای پروردگارتان را انکار می‌کنید؟!"},{"number":66,"arabic":"فِيهِمَا عَيْنَانِ نَضَّاخَتَانِ","translationFa":"در آنها دو چشمه جوشنده است!"},{"number":67,"arabic":"فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ","translationFa":"پس کدامین نعمتهای پروردگارتان را انکار می‌کنید؟!"},{"number":68,"arabic":"فِيهِمَا فَٰكِهَةٌۭ وَنَخْلٌۭ وَرُمَّانٌۭ","translationFa":"در آنها میوه‌های فراوان و درخت خرما و انار است!"},{"number":69,"arabic":"فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ","translationFa":"پس کدامین نعمتهای پروردگارتان را انکار می‌کنید؟!"},{"number":70,"arabic":"فِيهِنَّ خَيْرَٰتٌ حِسَانٌۭ","translationFa":"و در آن باغهای بهشتی زنانی نیکو خلق و زیبایند!"},{"number":71,"arabic":"فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ","translationFa":"پس کدامین نعمتهای پروردگارتان را انکار می‌کنید؟!"},{"number":72,"arabic":"حُورٌۭ مَّقْصُورَٰتٌۭ فِى ٱلْخِيَامِ","translationFa":"حوریانی که در خیمه���های بهشتی مستورند!"},{"number":73,"arabic":"فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ","translationFa":"پس کدامین نعمتهای پروردگارتان را انکار می‌کنید؟!"},{"number":74,"arabic":"لَمْ يَطْمِثْهُنَّ إِنسٌۭ قَبْلَهُمْ وَلَا جَآنٌّۭ","translationFa":"هیچ انس و جنّ پیش از ایشان با آنها تماس نگرفته (و دوشیزه‌اند)!"},{"number":75,"arabic":"فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ","translationFa":"پس کدامین نعمتهای پروردگارتان را انکار می‌کنید؟!"},{"number":76,"arabic":"مُتَّكِـِٔينَ عَلَىٰ رَفْرَفٍ خُضْرٍۢ وَعَبْقَرِىٍّ حِسَانٍۢ","translationFa":"این در حالی است که بهشتیان بر تختهایی تکیه زده‌اند که با بهترین و زیباترین پارچه‌های سبزرنگ پوشانده شده است."},{"number":77,"arabic":"فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ","translationFa":"پس کدامین نعمتهای پروردگارتان را انکار می‌کنید؟!"},{"number":78,"arabic":"تَبَٰرَكَ ٱسْمُ رَبِّكَ ذِى ٱلْجَلَٰلِ وَٱلْإِكْرَامِ","translationFa":"پربرکت و زوال‌ناپذیر است نام پروردگار صاحب جلال و بزرگوار تو!"}],"56":[{"number":1,"arabic":"بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ إِذَا وَقَعَتِ ٱلْوَاقِعَةُ","translationFa":"هنگامی که واقعه عظیم (قیامت) واقع شود،"},{"number":2,"arabic":"لَيْسَ لِوَقْعَتِهَا كَاذِبَةٌ","translationFa":"هیچ کس نمی‌تواند آن را انکار کند!"},{"number":3,"arabic":"خَافِضَةٌۭ رَّافِعَةٌ","translationFa":"(این واقعه) گروهی را پایین می‌آورد و گروهی را بالا می‌برد!"},{"number":4,"arabic":"إِذَا رُجَّتِ ٱلْأَرْضُ رَجًّۭا","translationFa":"در آن هنگام که زمین بشدّت به لرزه درمی‌آید،"},{"number":5,"arabic":"وَبُسَّتِ ٱلْجِبَالُ بَسًّۭا","translationFa":"و کوه‌ها در هم کوبیده می‌شود،"},{"number":6,"arabic":"فَكَانَتْ هَبَآءًۭ مُّنۢبَثًّۭا","translationFa":"و بصورت غبار پراکنده درمی‌آید،"},{"number":7,"arabic":"وَكُنتُمْ أَزْوَٰجًۭا ثَلَٰثَةًۭ","translationFa":"و شما سه گروه خواهید بود!"},{"number":8,"arabic":"فَأَصْحَٰبُ ٱلْمَيْمَنَةِ مَآ أَصْحَٰبُ ٱلْمَيْمَنَةِ","translationFa":"(نخست) سعادتمندان و خجستگان (هستند)؛ چه سعادتمندان و خجستگانی!"},{"number":9,"arabic":"وَأَصْحَٰبُ ٱلْمَشْـَٔمَةِ مَآ أَصْحَٰبُ ٱلْمَشْـَٔمَةِ","translationFa":"گروه دیگر شقاوتمندان و شومانند، چه شقاوتمندان و شومانی!"},{"number":10,"arabic":"وَٱلسَّٰبِقُونَ ٱلسَّٰبِقُونَ","translationFa":"و (سومین گروه) پیشگامان پیشگامند،"},{"number":11,"arabic":"أُو۟لَٰٓئِكَ ٱلْمُقَرَّبُونَ","translationFa":"آنها مقرّبانند!"},{"number":12,"arabic":"فِى جَنَّٰتِ ٱلنَّعِيمِ","translationFa":"در باغهای پرنعمت بهشت (جای دارند)!"},{"number":13,"arabic":"ثُلَّةٌۭ مِّنَ ٱلْأَوَّلِينَ","translationFa":"گروه زیادی (از آنها) از امّتهای نخستینند،"},{"number":14,"arabic":"وَقَلِيلٌۭ مِّنَ ٱلْءَاخِرِينَ","translationFa":"و اندکی از امّت آخرین!"},{"number":15,"arabic":"عَلَىٰ سُرُرٍۢ مَّوْضُونَةٍۢ","translationFa":"آنها [= مقرّبان‌] بر تختهایی که صف‌کشیده و به هم پیوسته است قراردارند،"},{"number":16,"arabic":"مُّتَّكِـِٔينَ عَلَيْهَا مُتَقَٰبِلِينَ","translationFa":"در حالی که بر آن تکیه زده و رو به روی یکدیگرند!"},{"number":17,"arabic":"يَطُوفُ عَلَيْهِمْ وِلْدَٰنٌۭ مُّخَلَّدُونَ","translationFa":"نوجوانانی جاودان (در شکوه و طراوت) پیوسته گرداگرد آنان می‌گردند،"},{"number":18,"arabic":"بِأَكْوَابٍۢ وَأَبَارِيقَ وَكَأْسٍۢ مِّن مَّعِينٍۢ","translationFa":"با قدحها و کوزه‌ها و جامهایی از نهرهای جاری ��هشتی (و شراب طهور)!"},{"number":19,"arabic":"لَّا يُصَدَّعُونَ عَنْهَا وَلَا يُنزِفُونَ","translationFa":"امّا شرابی که از آن درد سر نمی‌گیرند و نه مست می‌شوند!"},{"number":20,"arabic":"وَفَٰكِهَةٍۢ مِّمَّا يَتَخَيَّرُونَ","translationFa":"و میوه‌هایی از هر نوع که انتخاب کنند،"},{"number":21,"arabic":"وَلَحْمِ طَيْرٍۢ مِّمَّا يَشْتَهُونَ","translationFa":"و گوشت پرنده از هر نوع که مایل باشند!"},{"number":22,"arabic":"وَحُورٌ عِينٌۭ","translationFa":"و همسرانی از حور العین دارند،"},{"number":23,"arabic":"كَأَمْثَٰلِ ٱللُّؤْلُؤِ ٱلْمَكْنُونِ","translationFa":"همچون مروارید در صدف پنهان!"},{"number":24,"arabic":"جَزَآءًۢ بِمَا كَانُوا۟ يَعْمَلُونَ","translationFa":"اینها پاداشی است در برابر اعمالی که انجام می‌دادند!"},{"number":25,"arabic":"لَا يَسْمَعُونَ فِيهَا لَغْوًۭا وَلَا تَأْثِيمًا","translationFa":"در آن (باغهای بهشتی) نه لغو و بیهوده‌ای می‌شنوند نه سخنان گناه آلود؛"},{"number":26,"arabic":"إِلَّا قِيلًۭا سَلَٰمًۭا سَلَٰمًۭا","translationFa":"تنها چیزی که می‌شنوند «سلام» است «سلام»!"},{"number":27,"arabic":"وَأَصْحَٰبُ ٱلْيَمِينِ مَآ أَصْحَٰبُ ٱلْيَمِينِ","translationFa":"و اصحاب یمین و خجستگان، چه اصحاب یمین و خجستگانی!"},{"number":28,"arabic":"فِى سِدْرٍۢ مَّخْضُودٍۢ","translationFa":"آنها در سایه درختان «سِدر» بی‌خار قرار دارند،"},{"number":29,"arabic":"وَطَلْحٍۢ مَّنضُودٍۢ","translationFa":"و در سایه درخت «طلح» پربرگ [= درختی خوشرنگ و خوشبو]،"},{"number":30,"arabic":"وَظِلٍّۢ مَّمْدُودٍۢ","translationFa":"و سایه کشیده و گسترده،"},{"number":31,"arabic":"وَمَآءٍۢ مَّسْكُوبٍۢ","translationFa":"و در کنار آبشارها،"},{"number":32,"arabic":"وَفَٰكِهَةٍۢ كَثِيرَةٍۢ","translationFa":"و میوه‌های فراوان،"},{"number":33,"arabic":"لَّا مَقْطُوعَةٍۢ وَلَا مَمْنُوعَةٍۢ","translationFa":"که هرگز قطع و ممنوع نمی‌شود،"},{"number":34,"arabic":"وَفُرُشٍۢ مَّرْفُوعَةٍ","translationFa":"و همسرانی بلندمرتبه!"},{"number":35,"arabic":"إِنَّآ أَنشَأْنَٰهُنَّ إِنشَآءًۭ","translationFa":"ما آنها را آفرینش نوینی بخشیدیم،"},{"number":36,"arabic":"فَجَعَلْنَٰهُنَّ أَبْكَارًا","translationFa":"و همه را دوشیزه قرار دادیم،"},{"number":37,"arabic":"عُرُبًا أَتْرَابًۭا","translationFa":"زنانی که تنها به همسرشان عشق می‌ورزند و خوش زبان و فصیح و هم سن و سالند!"},{"number":38,"arabic":"لِّأَصْحَٰبِ ٱلْيَمِينِ","translationFa":"اینها همه برای اصحاب یمین است،"},{"number":39,"arabic":"ثُلَّةٌۭ مِّنَ ٱلْأَوَّلِينَ","translationFa":"که گروهی از امّتهای نخستینند،"},{"number":40,"arabic":"وَثُلَّةٌۭ مِّنَ ٱلْءَاخِرِينَ","translationFa":"و گروهی از امّتهای آخرین!"},{"number":41,"arabic":"وَأَصْحَٰبُ ٱلشِّمَالِ مَآ أَصْحَٰبُ ٱلشِّمَالِ","translationFa":"و اصحاب شمال، چه اصحاب شمالی (که نامه اعمالشان به نشانه جرمشان به دست چپ آنها داده می‌شود)!"},{"number":42,"arabic":"فِى سَمُومٍۢ وَحَمِيمٍۢ","translationFa":"آنها در میان بادهای کشنده و آب سوزان قرار دارند،"},{"number":43,"arabic":"وَظِلٍّۢ مِّن يَحْمُومٍۢ","translationFa":"و در سایه دودهای متراکم و آتشزا!"},{"number":44,"arabic":"لَّا بَارِدٍۢ وَلَا كَرِيمٍ","translationFa":"سایه‌ای که نه خنک است و نه آرامبخش!"},{"number":45,"arabic":"إِنَّهُمْ كَانُوا۟ قَبْلَ ذَٰلِكَ مُتْرَفِينَ","translationFa":"آنها پیش از این (در عالم دنیا) مست و مغرور نعمت بودند،"},{"number":46,"arabic":"وَكَانُوا۟ يُصِرُّونَ عَلَى ٱلْحِنثِ ٱلْعَظِيمِ","translationFa":"و بر گناهان بزرگ اصرار می‌ورزیدند،"},{"number":47,"arabic":"وَكَانُوا۟ يَقُولُونَ أَئِذَا مِتْنَا وَكُنَّا تُرَابًۭا وَعِظَٰمًا أَءِنَّا لَمَبْعُوثُونَ","translationFa":"و می‌گفتند: «هنگامی که ما مُردیم و خاک و استخوان شدیم، آیا برانگیخته خواهیم شد؟!"},{"number":48,"arabic":"أَوَءَابَآؤُنَا ٱلْأَوَّلُونَ","translationFa":"یا نیاکان نخستین ما (برانگیخته می‌شوند)؟!»"},{"number":49,"arabic":"قُلْ إِنَّ ٱلْأَوَّلِينَ وَٱلْءَاخِرِينَ","translationFa":"بگو: «اوّلین و آخرین،"},{"number":50,"arabic":"لَمَجْمُوعُونَ إِلَىٰ مِيقَٰتِ يَوْمٍۢ مَّعْلُومٍۢ","translationFa":"همگی در موعد روز معیّنی گردآوری می‌شوند،"},{"number":51,"arabic":"ثُمَّ إِنَّكُمْ أَيُّهَا ٱلضَّآلُّونَ ٱلْمُكَذِّبُونَ","translationFa":"سپس شما ای گمراهان تکذیب‌کننده!"},{"number":52,"arabic":"لَءَاكِلُونَ مِن شَجَرٍۢ مِّن زَقُّومٍۢ","translationFa":"قطعاً از درخت زقّوم می‌خورید،"},{"number":53,"arabic":"فَمَالِـُٔونَ مِنْهَا ٱلْبُطُونَ","translationFa":"و شکمها را از آن پر می‌کنید،"},{"number":54,"arabic":"فَشَٰرِبُونَ عَلَيْهِ مِنَ ٱلْحَمِيمِ","translationFa":"و روی آن از آب سوزان می‌نوشید،"},{"number":55,"arabic":"فَشَٰرِبُونَ شُرْبَ ٱلْهِيمِ","translationFa":"و همچون شتران مبتلا به بیماری عطش، از آن می‌آشامید!"},{"number":56,"arabic":"هَٰذَا نُزُلُهُمْ يَوْمَ ٱلدِّينِ","translationFa":"این است وسیله پذیرایی از آنها در قیامت!"},{"number":57,"arabic":"نَحْنُ خَلَقْنَٰكُمْ فَلَوْلَا تُصَدِّقُونَ","translationFa":"» ما شما را آفریدیم؛ پس چرا (آفرینش مجدّد را) تصدیق نمی‌کنید؟!"},{"number":58,"arabic":"أَفَرَءَيْتُم مَّا تُمْنُونَ","translationFa":"آیا از نطفه‌ای که در رحم می‌ریزید آگاهید؟!"},{"number":59,"arabic":"ءَأَنتُمْ تَخْلُقُونَهُۥٓ أَمْ نَحْنُ ٱلْخَٰلِقُونَ","translationFa":"آیا شما آن را (در دوران جنینی) آفرینش (پی در پی) می‌دهید یا ما آفریدگاریم؟!"},{"number":60,"arabic":"نَحْنُ قَدَّرْنَا بَيْنَكُمُ ٱلْمَوْتَ وَمَا نَحْنُ بِمَسْبُوقِينَ","translationFa":"ما در میان شما مرگ را مقدّر ساختیم؛ و هرگز کسی بر ما پیشی نمی‌گیرد!"},{"number":61,"arabic":"عَلَىٰٓ أَن نُّبَدِّلَ أَمْثَٰلَكُمْ وَنُنشِئَكُمْ فِى مَا لَا تَعْلَمُونَ","translationFa":"تا گروهی را به جای گروه دیگری بیاوریم و شما را در جهانی که نمی‌دانید آفرینش تازه‌ای بخشیم!"},{"number":62,"arabic":"وَلَقَدْ عَلِمْتُمُ ٱلنَّشْأَةَ ٱلْأُولَىٰ فَلَوْلَا تَذَكَّرُونَ","translationFa":"شما عالم نخستین را دانستید؛ چگونه متذکّر نمی‌شوید (که جهانی بعد از آن است)؟!"},{"number":63,"arabic":"أَفَرَءَيْتُم مَّا تَحْرُثُونَ","translationFa":"آیا هیچ درباره آنچه کشت می‌کنید اندیشیده‌اید؟!"},{"number":64,"arabic":"ءَأَنتُمْ تَزْرَعُونَهُۥٓ أَمْ نَحْنُ ٱلزَّٰرِعُونَ","translationFa":"آیا شما آن را می‌رویانید یا ما می‌رویانیم؟!"},{"number":65,"arabic":"لَوْ نَشَآءُ لَجَعَلْنَٰهُ حُطَٰمًۭا فَظَلْتُمْ تَفَكَّهُونَ","translationFa":"هرگاه بخواهیم آن را مبدّل به کاه در هم کوبیده می‌کنیم که تعجّب کنید!"},{"number":66,"arabic":"إِنَّا لَمُغْرَمُونَ","translationFa":"(بگونه‌ای که بگویید:) براستی ما زیان کرده‌ایم،"},{"number":67,"arabic":"بَلْ نَحْنُ مَحْرُومُونَ","translationFa":"بلکه ما بکلّی محرومیم!"},{"number":68,"arabic":"أَفَرَءَيْتُمُ ٱلْمَآءَ ٱلَّذِى تَشْرَبُونَ","translationFa":"آیا به آبی که می‌نوشید اندیشیده‌اید؟!"},{"number":69,"arabic":"ءَأَ��تُمْ أَنزَلْتُمُوهُ مِنَ ٱلْمُزْنِ أَمْ نَحْنُ ٱلْمُنزِلُونَ","translationFa":"آیا شما آن را از ابر نازل کرده‌اید یا ما نازل می‌کنیم؟!"},{"number":70,"arabic":"لَوْ نَشَآءُ جَعَلْنَٰهُ أُجَاجًۭا فَلَوْلَا تَشْكُرُونَ","translationFa":"هرگاه بخواهیم، این آب گوارا را تلخ و شور قرار می‌دهیم؛ پس چرا شکر نمی‌کنید؟!"},{"number":71,"arabic":"أَفَرَءَيْتُمُ ٱلنَّارَ ٱلَّتِى تُورُونَ","translationFa":"آیا درباره آتشی که می‌افروزید فکر کرده‌اید؟!"},{"number":72,"arabic":"ءَأَنتُمْ أَنشَأْتُمْ شَجَرَتَهَآ أَمْ نَحْنُ ٱلْمُنشِـُٔونَ","translationFa":"آیا شما درخت آن را آفریده‌اید یا ما آفریده‌ایم؟!"},{"number":73,"arabic":"نَحْنُ جَعَلْنَٰهَا تَذْكِرَةًۭ وَمَتَٰعًۭا لِّلْمُقْوِينَ","translationFa":"ما آن را وسیله یادآوری (برای همگان) و وسیله زندگی برای مسافران قرار داده‌ایم!"},{"number":74,"arabic":"فَسَبِّحْ بِٱسْمِ رَبِّكَ ٱلْعَظِيمِ","translationFa":"حال که چنین است به نام پروردگار بزرگت تسبیح کن (و او را پاک و منزّه بشمار)!"},{"number":75,"arabic":"۞ فَلَآ أُقْسِمُ بِمَوَٰقِعِ ٱلنُّجُومِ","translationFa":"سوگند به جایگاه ستارگان (و محل طلوع و غروب آنها)!"},{"number":76,"arabic":"وَإِنَّهُۥ لَقَسَمٌۭ لَّوْ تَعْلَمُونَ عَظِيمٌ","translationFa":"و این سوگندی است بسیار بزرگ، اگر بدانید!"},{"number":77,"arabic":"إِنَّهُۥ لَقُرْءَانٌۭ كَرِيمٌۭ","translationFa":"که آن، قرآن کریمی است،"},{"number":78,"arabic":"فِى كِتَٰبٍۢ مَّكْنُونٍۢ","translationFa":"که در کتاب محفوظی جای دارد،"},{"number":79,"arabic":"لَّا يَمَسُّهُۥٓ إِلَّا ٱلْمُطَهَّرُونَ","translationFa":"و جز پاکان نمی‌توانند به آن دست زنند [= دست یابند]."},{"number":80,"arabic":"تَنزِيلٌۭ مِّن رَّبِّ ٱلْعَٰلَمِينَ","translationFa":"آن از سوی پروردگار عالمیان نازل شده؛"},{"number":81,"arabic":"أَفَبِهَٰذَا ٱلْحَدِيثِ أَنتُم مُّدْهِنُونَ","translationFa":"آیا این سخن را [= این قرآن را با اوصافی که گفته شد] سست و کوچک می‌شمرید،"},{"number":82,"arabic":"وَتَجْعَلُونَ رِزْقَكُمْ أَنَّكُمْ تُكَذِّبُونَ","translationFa":"و به جای شکر روزیهایی که به شما داده شده آن را تکذیب می‌کنید؟!"},{"number":83,"arabic":"فَلَوْلَآ إِذَا بَلَغَتِ ٱلْحُلْقُومَ","translationFa":"پس چرا هنگامی که جان به گلوگاه می‌رسد (توانایی بازگرداندن آن را ندارید)؟!"},{"number":84,"arabic":"وَأَنتُمْ حِينَئِذٍۢ تَنظُرُونَ","translationFa":"و شما در این حال نظاره می‌کنید (و کاری از دستتان ساخته نیست)؛"},{"number":85,"arabic":"وَنَحْنُ أَقْرَبُ إِلَيْهِ مِنكُمْ وَلَٰكِن لَّا تُبْصِرُونَ","translationFa":"و ما از شما به او نزدیکتریم ولی نمی‌بینید!"},{"number":86,"arabic":"فَلَوْلَآ إِن كُنتُمْ غَيْرَ مَدِينِينَ","translationFa":"اگر هرگز در برابر اعمالتان جزا داده نمی‌شوید،"},{"number":87,"arabic":"تَرْجِعُونَهَآ إِن كُنتُمْ صَٰدِقِينَ","translationFa":"پس آن (روح) را بازگردانید اگر راست می‌گویید!"},{"number":88,"arabic":"فَأَمَّآ إِن كَانَ مِنَ ٱلْمُقَرَّبِينَ","translationFa":"پس اگر او از مقرّبان باشد،"},{"number":89,"arabic":"فَرَوْحٌۭ وَرَيْحَانٌۭ وَجَنَّتُ نَعِيمٍۢ","translationFa":"در رَوح و ریحان و بهشت پرنعمت است!"},{"number":90,"arabic":"وَأَمَّآ إِن كَانَ مِنْ أَصْحَٰبِ ٱلْيَمِينِ","translationFa":"امّا اگر از اصحاب یمین باشد،"},{"number":91,"arabic":"فَسَلَٰمٌۭ لَّكَ مِنْ أَصْحَٰبِ ٱلْيَمِينِ","translationFa":"(به او گفته می‌شود:) سلام بر تو از سوی دوستانت که از اصحاب یمینند!"},{"number":92,"arabic":"وَأَمَّآ إِن كَانَ مِنَ ٱلْمُكَذِّبِينَ ٱلضَّآلِّينَ","translationFa":"امّا اگر او از تکذیب‌کنندگان گمراه باشد،"},{"number":93,"arabic":"فَنُزُلٌۭ مِّنْ حَمِيمٍۢ","translationFa":"با آب جوشان دوزخ از او پذیرایی می‌شوید!"},{"number":94,"arabic":"وَتَصْلِيَةُ جَحِيمٍ","translationFa":"و سرنوشت او ورود در آتش جهنّم است،"},{"number":95,"arabic":"إِنَّ هَٰذَا لَهُوَ حَقُّ ٱلْيَقِينِ","translationFa":"این مطلب حقّ و یقین است!"},{"number":96,"arabic":"فَسَبِّحْ بِٱسْمِ رَبِّكَ ٱلْعَظِيمِ","translationFa":"پس به نام پروردگار بزرگت تسبیح کن (و او را منزّه بشمار)!"}],"62":[{"number":1,"arabic":"بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ يُسَبِّحُ لِلَّهِ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ ٱلْمَلِكِ ٱلْقُدُّوسِ ٱلْعَزِيزِ ٱلْحَكِيمِ","translationFa":"آنچه در آسمانها و آنچه در زمین است همواره تسبیح خدا می‌گویند، خداوندی که مالک و حاکم است و از هر عیب و نقصی مبرا، و عزیز و حکیم است!"},{"number":2,"arabic":"هُوَ ٱلَّذِى بَعَثَ فِى ٱلْأُمِّيِّۦنَ رَسُولًۭا مِّنْهُمْ يَتْلُوا۟ عَلَيْهِمْ ءَايَٰتِهِۦ وَيُزَكِّيهِمْ وَيُعَلِّمُهُمُ ٱلْكِتَٰبَ وَٱلْحِكْمَةَ وَإِن كَانُوا۟ مِن قَبْلُ لَفِى ضَلَٰلٍۢ مُّبِينٍۢ","translationFa":"و کسی است که در میان جمعیت درس نخوانده رسولی از خودشان برانگیخت که آیاتش را بر آنها می‌خواند و آنها را تزکیه می‌کند و به آنان کتاب (قرآن) و حکمت می‌آموزد هر چند پیش از آن در گمراهی آشکاری بودند!"},{"number":3,"arabic":"وَءَاخَرِينَ مِنْهُمْ لَمَّا يَلْحَقُوا۟ بِهِمْ ۚ وَهُوَ ٱلْعَزِيزُ ٱلْحَكِيمُ","translationFa":"و (همچنین) رسول است بر گروه دیگری که هنوز به آنها ملحق نشده‌اند؛ و او عزیز و حکیم است!"},{"number":4,"arabic":"ذَٰلِكَ فَضْلُ ٱللَّهِ يُؤْتِيهِ مَن يَشَآءُ ۚ وَٱللَّهُ ذُو ٱلْفَضْلِ ٱلْعَظِيمِ","translationFa":"این فضل خداست که به هر کس بخواهد (و شایسته بداند) می‌بخشد؛ و خداوند صاحب فضل عظیم است!"},{"number":5,"arabic":"مَثَلُ ٱلَّذِينَ حُمِّلُوا۟ ٱلتَّوْرَىٰةَ ثُمَّ لَمْ يَحْمِلُوهَا كَمَثَلِ ٱلْحِمَارِ يَحْمِلُ أَسْفَارًۢا ۚ بِئْسَ مَثَلُ ٱلْقَوْمِ ٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَٰتِ ٱللَّهِ ۚ وَٱللَّهُ لَا يَهْدِى ٱلْقَوْمَ ٱلظَّٰلِمِينَ","translationFa":"کسانی که مکلف به تورات شدند ولی حق آن را ادا نکردند، مانند درازگوشی هستند که کتابهایی حمل می‌کند، (آن را بر دوش می‌کشد اما چیزی از آن نمی‌فهمد)! گروهی که آیات خدا را انکار کردند مثال بدی دارند، و خداوند قوم ستمگر را هدایت نمی‌کند!"},{"number":6,"arabic":"قُلْ يَٰٓأَيُّهَا ٱلَّذِينَ هَادُوٓا۟ إِن زَعَمْتُمْ أَنَّكُمْ أَوْلِيَآءُ لِلَّهِ مِن دُونِ ٱلنَّاسِ فَتَمَنَّوُا۟ ٱلْمَوْتَ إِن كُنتُمْ صَٰدِقِينَ","translationFa":"بگو: «ای یهودیان! اگر گمان می‌کنید که (فقط) شما دوستان خدائید نه سایر مردم، پس آرزوی مرگ کنید اگر راست می‌گویید (تا به لقای محبوبتان برسید)!»"},{"number":7,"arabic":"وَلَا يَتَمَنَّوْنَهُۥٓ أَبَدًۢا بِمَا قَدَّمَتْ أَيْدِيهِمْ ۚ وَٱللَّهُ عَلِيمٌۢ بِٱلظَّٰلِمِينَ","translationFa":"ولی آنان هرگز تمنای مرگ نمی‌کنند بخاطر اعمالی که از پیش فرستاده‌اند؛ و خداوند ظالمان را بخوبی می‌شناسد!"},{"number":8,"arabic":"قُلْ إِنَّ ٱلْمَوْتَ ٱلَّذِى تَفِرُّونَ مِنْهُ فَإِنَّهُۥ مُلَٰقِيكُمْ ۖ ثُمَّ تُرَدُّونَ إِلَىٰ عَٰلِمِ ٱلْغَيْبِ وَٱلشَّهَٰدَةِ فَيُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ","translationFa":"بگو: «این مرگی که از آن فرار می‌کنید سرانجام با شما ملاقات خواهد کرد؛ سپس به سوی کسی که دانای پنهان و آشکار است بازگردانده می‌شوید؛ آنگاه شما را از آنچه انجام می‌دادید خبر می‌دهد!»"},{"number":9,"arabic":"يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِذَا نُودِىَ لِلصَّلَوٰةِ مِن يَوْمِ ٱلْجُمُعَةِ فَٱسْعَوْا۟ إِلَىٰ ذِكْرِ ٱللَّهِ وَذَرُوا۟ ٱلْبَيْعَ ۚ ذَٰلِكُمْ خَيْرٌۭ لَّكُمْ إِن كُنتُمْ تَعْلَمُونَ","translationFa":"ای کسانی که ایمان آورده‌اید! هنگامی که برای نماز روز جمعه اذان گفته شود، به سوی ذکر خدا بشتابید و خرید و فروش را رها کنید که این برای شما بهتر است اگر می‌دانستید!"},{"number":10,"arabic":"فَإِذَا قُضِيَتِ ٱلصَّلَوٰةُ فَٱنتَشِرُوا۟ فِى ٱلْأَرْضِ وَٱبْتَغُوا۟ مِن فَضْلِ ٱللَّهِ وَٱذْكُرُوا۟ ٱللَّهَ كَثِيرًۭا لَّعَلَّكُمْ تُفْلِحُونَ","translationFa":"و هنگامی که نماز پایان گرفت (شما آزادید) در زمین پراکنده شوید و از فضل خدا بطلبید، و خدا را بسیار یاد کنید شاید رستگار شوید!"},{"number":11,"arabic":"وَإِذَا رَأَوْا۟ تِجَٰرَةً أَوْ لَهْوًا ٱنفَضُّوٓا۟ إِلَيْهَا وَتَرَكُوكَ قَآئِمًۭا ۚ قُلْ مَا عِندَ ٱللَّهِ خَيْرٌۭ مِّنَ ٱللَّهْوِ وَمِنَ ٱلتِّجَٰرَةِ ۚ وَٱللَّهُ خَيْرُ ٱلرَّٰزِقِينَ","translationFa":"هنگامی که آنها تجارت یا سرگرمی و لهوی را ببینند پراکنده می‌شوند و به سوی آن می روند و تو را ایستاده به حال خود رها می‌کنند؛ بگو: آنچه نزد خداست بهتر از لهو و تجارت است، و خداوند بهترین روزی‌دهندگان است."}],"67":[{"number":1,"arabic":"بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ تَبَٰرَكَ ٱلَّذِى بِيَدِهِ ٱلْمُلْكُ وَهُوَ عَلَىٰ كُلِّ شَىْءٍۢ قَدِيرٌ","translationFa":"پربرکت و زوال‌ناپذیر است کسی که حکومت جهان هستی به دست اوست، و او بر هر چیز تواناست."},{"number":2,"arabic":"ٱلَّذِى خَلَقَ ٱلْمَوْتَ وَٱلْحَيَوٰةَ لِيَبْلُوَكُمْ أَيُّكُمْ أَحْسَنُ عَمَلًۭا ۚ وَهُوَ ٱلْعَزِيزُ ٱلْغَفُورُ","translationFa":"آن کس که مرگ و حیات را آفرید تا شما را بیازماید که کدام یک از شما بهتر عمل می‌کنید، و او شکست‌ناپذیر و بخشنده است."},{"number":3,"arabic":"ٱلَّذِى خَلَقَ سَبْعَ سَمَٰوَٰتٍۢ طِبَاقًۭا ۖ مَّا تَرَىٰ فِى خَلْقِ ٱلرَّحْمَٰنِ مِن تَفَٰوُتٍۢ ۖ فَٱرْجِعِ ٱلْبَصَرَ هَلْ تَرَىٰ مِن فُطُورٍۢ","translationFa":"همان کسی که هفت آسمان را بر فراز یکدیگر آفرید؛ در آفرینش خداوند رحمان هیچ تضادّ و عیبی نمی‌بینی! بار دیگر نگاه کن، آیا هیچ شکاف و خللی مشاهده می‌کنی؟!"},{"number":4,"arabic":"ثُمَّ ٱرْجِعِ ٱلْبَصَرَ كَرَّتَيْنِ يَنقَلِبْ إِلَيْكَ ٱلْبَصَرُ خَاسِئًۭا وَهُوَ حَسِيرٌۭ","translationFa":"بار دیگر (به عالم هستی) نگاه کن، سرانجام چشمانت (در جستجوی خلل و نقصان ناکام مانده) به سوی تو باز می‌گردد در حالی که خسته و ناتوان است!"},{"number":5,"arabic":"وَلَقَدْ زَيَّنَّا ٱلسَّمَآءَ ٱلدُّنْيَا بِمَصَٰبِيحَ وَجَعَلْنَٰهَا رُجُومًۭا لِّلشَّيَٰطِينِ ۖ وَأَعْتَدْنَا لَهُمْ عَذَابَ ٱلسَّعِيرِ","translationFa":"ما آسمان پایین (نزدیک) را با چراغهای فروزانی زینت بخشیدیم، و آنها [= شهابها] را تیرهایی برای شیاطین قرار دادیم، و برای آنان عذاب آتش فروزان فراهم ساختیم!"},{"number":6,"arabic":"وَلِلَّذِينَ كَفَرُوا۟ بِرَبِّهِمْ عَذَابُ جَهَنَّمَ ۖ وَبِئْسَ ٱلْمَصِيرُ","translationFa":"و برای کسانی که به پروردگارشان کافر شدند عذاب جهنّم است، و بد فرجامی است!"},{"number":7,"arabic":"إِذَآ أُلْقُوا۟ فِيهَا سَمِعُوا۟ لَهَا شَهِيقًۭا وَهِىَ تَفُورُ","translationFa":"هنگامی که در آن افکنده شوند صدای وحشتناکی از آن می‌شنوند، و این در حالی است که پیوسته می‌جوشد!"},{"number":8,"arabic":"تَكَادُ تَمَيَّزُ مِنَ ٱلْغَيْظِ ۖ كُلَّمَآ أُلْقِىَ فِيهَا فَوْجٌۭ سَأَلَهُمْ خَزَنَتُهَآ أَلَمْ يَأْتِكُمْ نَذِيرٌۭ","translationFa":"نزدیک است (دوزخ) از شدّت غضب پاره پاره شود؛ هر زمان که گروهی در آن افکنده می‌شوند، نگهبانان دوزخ از آنها می‌پرسند: «مگر بیم‌دهنده الهی به سراغ شما نیامد؟!»"},{"number":9,"arabic":"قَالُوا۟ بَلَىٰ قَدْ جَآءَنَا نَذِيرٌۭ فَكَذَّبْنَا وَقُلْنَا مَا نَزَّلَ ٱللَّهُ مِن شَىْءٍ إِنْ أَنتُمْ إِلَّا فِى ضَلَٰلٍۢ كَبِيرٍۢ","translationFa":"می‌گویند: «آری، بیم‌دهنده به سراغ ما آمد، ولی ما او را تکذیب کردیم و گفتیم: خداوند هرگز چیزی نازل نکرده، و شما در گمراهی بزرگی هستید!»"},{"number":10,"arabic":"وَقَالُوا۟ لَوْ كُنَّا نَسْمَعُ أَوْ نَعْقِلُ مَا كُنَّا فِىٓ أَصْحَٰبِ ٱلسَّعِيرِ","translationFa":"و می‌گویند: «اگر ما گوش شنوا داشتیم یا تعقّل می‌کردیم، در میان دوزخیان نبودیم!»"},{"number":11,"arabic":"فَٱعْتَرَفُوا۟ بِذَنۢبِهِمْ فَسُحْقًۭا لِّأَصْحَٰبِ ٱلسَّعِيرِ","translationFa":"اینجاست که به گناه خود اعتراف می‌کنند؛ دور باشند دوزخیان از رحمت خدا!"},{"number":12,"arabic":"إِنَّ ٱلَّذِينَ يَخْشَوْنَ رَبَّهُم بِٱلْغَيْبِ لَهُم مَّغْفِرَةٌۭ وَأَجْرٌۭ كَبِيرٌۭ","translationFa":"(امّا) کسانی که از پروردگارشان در نهان می‌ترسند، مسلّماً آمرزش و پاداش بزرگی دارند!"},{"number":13,"arabic":"وَأَسِرُّوا۟ قَوْلَكُمْ أَوِ ٱجْهَرُوا۟ بِهِۦٓ ۖ إِنَّهُۥ عَلِيمٌۢ بِذَاتِ ٱلصُّدُورِ","translationFa":"گفتار خود را پنهان کنید یا آشکار (تفاوتی نمی‌کند)، او به آنچه در سینه‌هاست آگاه است!"},{"number":14,"arabic":"أَلَا يَعْلَمُ مَنْ خَلَقَ وَهُوَ ٱللَّطِيفُ ٱلْخَبِيرُ","translationFa":"آیا آن کسی که موجودات را آفریده از حال آنها آگاه نیست؟! در حالی که او (از اسرار دقیق) باخبر و آگاه است!"},{"number":15,"arabic":"هُوَ ٱلَّذِى جَعَلَ لَكُمُ ٱلْأَرْضَ ذَلُولًۭا فَٱمْشُوا۟ فِى مَنَاكِبِهَا وَكُلُوا۟ مِن رِّزْقِهِۦ ۖ وَإِلَيْهِ ٱلنُّشُورُ","translationFa":"او کسی است که زمین را برای شما رام کرد، بر شانه‌های آن راه بروید و از روزیهای خداوند بخورید؛ و بازگشت و اجتماع همه به سوی اوست!"},{"number":16,"arabic":"ءَأَمِنتُم مَّن فِى ٱلسَّمَآءِ أَن يَخْسِفَ بِكُمُ ٱلْأَرْضَ فَإِذَا هِىَ تَمُورُ","translationFa":"آیا خود را از عذاب کسی که حاکم بر آسمان است در امان می‌دانید که دستور دهد زمین بشکافد و شما را فرو برد و به لرزش خود ادامه دهد؟!"},{"number":17,"arabic":"أَمْ أَمِنتُم مَّن فِى ٱلسَّمَآءِ أَن يُرْسِلَ عَلَيْكُمْ حَاصِبًۭا ۖ فَسَتَعْلَمُونَ كَيْفَ نَذِيرِ","translationFa":"یا خود را از عذاب خداوند آسمان در امان می‌دانید که تندبادی پر از سنگریزه بر شما فرستد؟! و بزودی خواهید دانست تهدیدهای من چگونه است!"},{"number":18,"arabic":"وَلَقَدْ كَذَّبَ ٱلَّذِينَ مِن قَبْلِهِمْ فَكَيْفَ كَانَ نَكِيرِ","translationFa":"کسانی که پیش از آنان بودند (آیات الهی را) تکذیب کردند، امّا (ببین) مجازات من چگونه بود!"},{"number":19,"arabic":"أَوَلَمْ يَرَوْا۟ إِلَى ٱلطَّيْرِ فَوْقَهُمْ صَٰٓفَّٰتٍۢ وَيَقْبِضْنَ ۚ مَا يُمْسِكُهُنَّ إِلَّا ٱلرَّحْمَٰنُ ۚ إِنَّهُۥ بِكُلِّ شَىْءٍۭ بَصِيرٌ","translationFa":"آیا به پرندگانی که بالای سرشان است، و گاه بالهای خود را گسترده و گاه جمع می‌کنند، نگاه نکردند؟! جز خداوند رحمان کسی آنها را بر فراز آسمان نگه نمی‌دارد، چرا که او به هر چیز بیناست!"},{"number":20,"arabic":"أَمَّنْ هَٰذَا ٱلَّذِى هُوَ جُندٌۭ لَّكُمْ يَنصُرُكُم مِّن دُونِ ٱلرَّحْمَٰنِ ۚ إِنِ ٱلْكَٰفِرُونَ إِلَّا فِى غُرُورٍ","translationFa":"آیا این کسی که لشکر شماست می‌تواند شما را در برابر خداوند یاری دهد؟ ولی کافران تنها گرفتار فریبند!"},{"number":21,"arabic":"أَمَّنْ هَٰذَا ٱلَّذِى يَرْزُقُكُمْ إِنْ أَمْسَكَ رِزْقَهُۥ ۚ بَل لَّجُّوا۟ فِى عُتُوٍّۢ وَنُفُورٍ","translationFa":"یا آن کسی که شما را روزی می‌دهد، اگر روزیش را بازدارد (چه کسی می‌تواند نیاز شما را تأمین کند)؟! ولی آنها در سرکشی و فرار از حقیقت لجاجت می‌ورزند!"},{"number":22,"arabic":"أَفَمَن يَمْشِى مُكِبًّا عَلَىٰ وَجْهِهِۦٓ أَهْدَىٰٓ أَمَّن يَمْشِى سَوِيًّا عَلَىٰ صِرَٰطٍۢ مُّسْتَقِيمٍۢ","translationFa":"آیا کسی که به رو افتاده حرکت می‌کند به هدایت نزدیکتر است یا کسی که راست‌قامت در صراط مستقیم گام برمی‌دارد؟!"},{"number":23,"arabic":"قُلْ هُوَ ٱلَّذِىٓ أَنشَأَكُمْ وَجَعَلَ لَكُمُ ٱلسَّمْعَ وَٱلْأَبْصَٰرَ وَٱلْأَفْـِٔدَةَ ۖ قَلِيلًۭا مَّا تَشْكُرُونَ","translationFa":"بگو: «او کسی است که شما را آفرید و برای شما گوش و چشم و قلب قرار داد؛ امّا کمتر سپاسگزاری می‌کنید!»"},{"number":24,"arabic":"قُلْ هُوَ ٱلَّذِى ذَرَأَكُمْ فِى ٱلْأَرْضِ وَإِلَيْهِ تُحْشَرُونَ","translationFa":"بگو: «او کسی است که شما را در زمین آفرید و به سوی او محشور می‌شوید!»"},{"number":25,"arabic":"وَيَقُولُونَ مَتَىٰ هَٰذَا ٱلْوَعْدُ إِن كُنتُمْ صَٰدِقِينَ","translationFa":"آنها می‌گویند: «اگر راست می‌گویید این وعده قیامت چه زمانی است؟!»"},{"number":26,"arabic":"قُلْ إِنَّمَا ٱلْعِلْمُ عِندَ ٱللَّهِ وَإِنَّمَآ أَنَا۠ نَذِيرٌۭ مُّبِينٌۭ","translationFa":"بگو: «علم آن تنها نزد خداست؛ و من فقط بیم‌دهنده آشکاری هستم!»"},{"number":27,"arabic":"فَلَمَّا رَأَوْهُ زُلْفَةًۭ سِيٓـَٔتْ وُجُوهُ ٱلَّذِينَ كَفَرُوا۟ وَقِيلَ هَٰذَا ٱلَّذِى كُنتُم بِهِۦ تَدَّعُونَ","translationFa":"هنگامی که آن (وعده الهی) را از نزدیک می‌بینند، صورت کافران زشت و سیاه می‌گردد، و به آنها گفته می‌شود: «این همان چیزی است که تقاضای آن را داشتید»!"},{"number":28,"arabic":"قُلْ أَرَءَيْتُمْ إِنْ أَهْلَكَنِىَ ٱللَّهُ وَمَن مَّعِىَ أَوْ رَحِمَنَا فَمَن يُجِيرُ ٱلْكَٰفِرِينَ مِنْ عَذَابٍ أَلِيمٍۢ","translationFa":"بگو: «به من خبر دهید اگر خداوند مرا و تمام کسانی را که با من هستند هلاک کند، یا مورد ترحّم قرار دهد، چه کسی کافران را از عذاب دردناک پناه می‌دهد؟!»"},{"number":29,"arabic":"قُلْ هُوَ ٱلرَّحْمَٰنُ ءَامَنَّا بِهِۦ وَعَلَيْهِ تَوَكَّلْنَا ۖ فَسَتَعْلَمُونَ مَنْ هُوَ فِى ضَلَٰلٍۢ مُّبِينٍۢ","translationFa":"بگو: «او خداوند رحمان است، ما به او ایمان آورده و بر او توکّل کرده‌ایم؛ و بزودی می‌دانید چه کسی در گمراهی آشکار است!»"},{"number":30,"arabic":"قُلْ أَرَءَيْتُمْ إِنْ أَصْبَحَ مَآؤُكُمْ غَوْرًۭا فَمَن يَأْتِيكُم بِمَآءٍۢ مَّعِينٍۭ","translationFa":"بگو: «به من خبر دهید اگر آبهای (سرزمین) شما در زمین فرو رود، چه کسی می‌تواند آب جاری و گوارا در دسترس شما قرار دهد؟!»"}],"97":[{"number":1,"arabic":"إِنَّا أَنْزَلْنَاهُ فِي لَيْلَةِ الْقَدْرِ","translationFa":"ما آن (قرآن) را در شب قدر نازل کردیم!"},{"number":2,"arabic":"وَمَا أَدْرَاكَ مَا لَيْلَةُ الْقَدْرِ","translationFa":"و تو چه می‌دانی شب قدر چیست؟!"},{"number":3,"arabic":"لَيْلَةُ الْقَدْرِ خَيْرٌ مِنْ أَلْفِ شَهْرٍ","translationFa":"شب قدر بهتر از هزار ماه است!"},{"number":4,"arabic":"تَنَزَّلُ الْمَلَائِكَةُ وَالرُّوحُ فِيهَا بِإِذْنِ رَبِّهِمْ مِنْ كُلِّ أَمْرٍ","translationFa":"فرشتگان و «روح» در آن شب به اذن پروردگارشان برای تقدیر هر کاری نازل می‌شوند."},{"number":5,"arabic":"سَلَامٌ هِيَ حَتَّىٰ مَطْلَعِ الْفَجْرِ","translationFa":"شبی است سرشار از سلامت و برکت تا طلوع سپیده صبح!"}],"112":[{"number":1,"arabic":"قُلْ هُوَ اللَّهُ أَحَدٌ","translationFa":"بگو: خداوند یکتا و یگانه است؛"},{"number":2,"arabic":"اللَّهُ الصَّمَدُ","translationFa":"خداوندی است که همه نیازمندان قصد او می‌کنند؛"},{"number":3,"arabic":"لَمْ يَلِدْ وَلَمْ يُولَدْ","translationFa":"نه کسی را زاده و نه از کسی زاده شده است،"},{"number":4,"arabic":"وَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌ","translationFa":"و هیچ کس شبیه و همتای او نبوده است!"}]};

export async function fetchSurahAyahs(
  surahNumber: number,
  fallbackAyahs?: QuranAyahItem[]
): Promise<QuranAyahItem[]> {
  if (BUNDLED_COMPLETE_SURAHS[surahNumber] && BUNDLED_COMPLETE_SURAHS[surahNumber].length > 0) {
    return BUNDLED_COMPLETE_SURAHS[surahNumber];
  }
  try {
    const cached = localStorage.getItem(QURAN_SURAH_CACHE_PREFIX + surahNumber);
    if (cached) {
      const parsed = JSON.parse(cached);
      if (Array.isArray(parsed) && parsed.length > 0) return parsed;
    }
  } catch {}

  try {
    const res = await fetch(`https://api.alquran.cloud/v1/surah/${surahNumber}/editions/quran-simple,fa.fooladvand`);
    if (res.ok) {
      const json = await res.json();
      if (json?.data && Array.isArray(json.data) && json.data.length >= 2) {
        const arAyahs = json.data[0].ayahs || [];
        const faAyahs = json.data[1].ayahs || [];
        const combined: QuranAyahItem[] = arAyahs.map((a: { numberInSurah: number; text: string }, idx: number) => ({
          number: a.numberInSurah || idx + 1,
          arabic: a.text,
          translationFa: faAyahs[idx]?.text || '',
        }));
        if (combined.length > 0) {
          try {
            localStorage.setItem(QURAN_SURAH_CACHE_PREFIX + surahNumber, JSON.stringify(combined));
          } catch {}
          return combined;
        }
      }
    }
  } catch {}

  return fallbackAyahs && fallbackAyahs.length > 0
    ? fallbackAyahs
    : [
        {
          number: 1,
          arabic: 'بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ',
          translationFa: 'به نام خداوند بخشنده مهربان (برای دریافت کامل تمام آیات این سوره یک‌بار به اینترنت متصل شوید تا برای همیشه در گوشی ذخیره شود).',
        },
      ];
}
